-- Clinician library resources for 2026-10-07: five of every kind and five on every topic.
-- Written on 2026-10-08 to replace the batch the 2026-10-07 run lost when GitHub rejected its push.
-- Generated with: python3 tools/therapist_resources_sql.py <the 125 slugs dated 2026-10-07>
-- An upsert on slug, so applying it twice is harmless.

on conflict (slug) do update set
  title      = excluded.title,
  kind       = excluded.kind,
  summary    = excluded.summary,
  goal       = excluded.goal,
  audience   = excluded.audience,
  duration   = excluded.duration,
  body_md    = excluded.body_md,
  fields     = excluded.fields,
  tags       = excluded.tags,
  created_at = excluded.created_at;
