insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('caffeine-and-light-cutoff-log', 'Caffeine and Light Cutoff Log', 'worksheet'::resource_kind, 'A one-week log of the last caffeine, the last bright screen and the time sleep actually came.', 'Use it to show a client which evening inputs are moving their sleep onset.', array['Adults', 'Teens']::text[], 'One week', 'Most clients have already heard that coffee and phones hurt sleep and have stopped listening, so do not lecture. Have them record three times a night for a week, last caffeine, last bright screen, and roughly when they fell asleep, plus a one-word note on how the night went. Review the week together and let the pattern make the argument. Energy drinks, pre-workout powders and decaf after dinner are the usual hidden caffeine. If nothing in the log moves sleep onset, that is useful too and points you elsewhere.', '[{"id": "f0", "type": "textarea", "label": "The time of my last caffeine today, and what it was"}, {"id": "f1", "type": "textarea", "label": "The time I put down the last bright screen"}, {"id": "f2", "type": "textarea", "label": "Roughly when I fell asleep"}, {"id": "f3", "type": "textarea", "label": "How the night went, in a word or two"}, {"id": "f4", "type": "textarea", "label": "After a week: what the log shows me about my evenings"}, {"id": "f5", "type": "textarea", "label": "One cutoff I am willing to move earlier next week"}]'::jsonb, array['sleep', 'self-monitoring', 'routines']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('commute-decompression-routine', 'Commute Decompression Routine', 'worksheet'::resource_kind, 'A planner for the ride or walk home that marks where the workday ends and the evening begins.', 'Use it to stop a client carrying the workday through the front door.', array['Adults']::text[], '20 minutes to plan, then daily', 'Useful for clients whose partner or kids get the leftover irritation from work, and for remote workers whose commute is a hallway. Help them pick a threshold, a train stop, a parking spot, closing the laptop lid, and attach three small acts to it: one that closes work, one that shifts the body, one that opens the evening. Keep the whole thing under ten minutes or it will not survive a bad day. The usual failure is checking email during the decompression; name that in advance and decide what the phone does.', '[{"id": "f0", "type": "textarea", "label": "My threshold: the moment the workday is over"}, {"id": "f1", "type": "textarea", "label": "One thing I do to close work (a note for tomorrow, a last look at the list)"}, {"id": "f2", "type": "textarea", "label": "One thing I do with my body between work and home"}, {"id": "f3", "type": "textarea", "label": "One thing that opens the evening for me"}, {"id": "f4", "type": "textarea", "label": "What my phone does during this time"}, {"id": "f5", "type": "textarea", "label": "After a week: what my family or I noticed at the door"}]'::jsonb, array['transitions', 'routines', 'stress', 'work']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('notification-triage-sheet', 'Notification Triage Sheet', 'worksheet'::resource_kind, 'A sort of every app that is allowed to interrupt a client into keep, batch or silence.', 'Use it to cut the pulls on a client''s attention down to the ones they chose.', array['Adults', 'Teens']::text[], '30 minutes', 'Have the client open their phone''s notification settings in session and go app by app; abstract conversations about screen time do nothing, this does. Each app lands in one of three columns: keep as it is, batch to a set check-in time, or silence entirely. Expect resistance around messaging apps and a fear of missing something; ask who actually needs to reach them within the hour and route only those through. Set a date two weeks out to review what was missed, which is almost always nothing.', '[{"id": "f0", "type": "textarea", "label": "Apps that can interrupt me right now (list them all)"}, {"id": "f1", "type": "textarea", "label": "Keep: the ones that truly need to reach me within the hour, and who is behind them"}, {"id": "f2", "type": "textarea", "label": "Batch: the ones I will check at set times, and when those times are"}, {"id": "f3", "type": "textarea", "label": "Silence: the ones that get nothing"}, {"id": "f4", "type": "textarea", "label": "What I am afraid I will miss"}, {"id": "f5", "type": "textarea", "label": "Two weeks later: what I actually missed, and what I got back"}]'::jsonb, array['attention', 'habits', 'boundaries']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('weak-ties-inventory', 'Weak Ties Inventory', 'worksheet'::resource_kind, 'An inventory of the familiar faces a lonely client already sees each week, and one small step with each.', 'Help a client build connection from the acquaintances they already have.', array['Adults', 'Teens']::text[], '30 minutes, then one week', 'For the client who says they have no one, the close friend they want feels miles away and the gap is paralyzing. This sheet points at the middle ground: the neighbor, the regular at the gym, the coworker from another team, the parent at pickup. List everyone they recognize on sight, then pick two and plan a step one size bigger than now, a name learned, a question asked, a short exchange extended. Keep the goal pleasant contact, not friendship, and review how the exchanges felt rather than how they went.', '[{"id": "f0", "type": "textarea", "label": "People I see most weeks and would recognize anywhere"}, {"id": "f1", "type": "textarea", "label": "The ones I already say hello to"}, {"id": "f2", "type": "textarea", "label": "Two I will take one step further this week"}, {"id": "f3", "type": "textarea", "label": "The step, one size bigger than what I do now"}, {"id": "f4", "type": "textarea", "label": "How each exchange felt, in the moment and after"}, {"id": "f5", "type": "textarea", "label": "What I notice about my week when I count these people in"}]'::jsonb, array['connection', 'support', 'social skills']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('caregiver-respite-menu', 'Caregiver Respite Menu', 'worksheet'::resource_kind, 'A menu of breaks in three sizes a caregiver can take without the person they care for coming to harm.', 'Use it to give a caregiver real, pre-arranged breaks instead of a vague instruction to rest.', array['Adults']::text[], '40 minutes', 'Caregivers hear self-care advice as one more task, and the obstacle is rarely motivation; it is that no break has been arranged. Build the menu in three sizes: ten-minute breaks that need no cover, half-day breaks that need someone to step in, and overnight or longer breaks that need real planning. For the two larger sizes, name the specific person or service and what they would need to know. Watch for guilt stated as logistics. Agree on one item from each row to take before you meet again.', '[{"id": "f0", "type": "textarea", "label": "Ten-minute breaks I can take with no cover at all"}, {"id": "f1", "type": "textarea", "label": "Half-day breaks, and who could cover for me"}, {"id": "f2", "type": "textarea", "label": "A longer break, and what it would take to arrange it"}, {"id": "f3", "type": "textarea", "label": "What the person covering needs to know, written down once"}, {"id": "f4", "type": "textarea", "label": "The thought that shows up when I imagine taking the break"}, {"id": "f5", "type": "textarea", "label": "The one break from each row I will take before next session"}]'::jsonb, array['pacing', 'support', 'burnout']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('survey-method-experiment', 'Survey Method Experiment', 'cbt'::resource_kind, 'A behavioral experiment in which the client asks several people what they would think in a feared situation.', 'Use it to test a belief about how others judge against what others actually say.', array['Adults', 'Teens']::text[], 'One week', 'Pick a belief about other people''s reactions, for instance that anyone would think less of someone who cried at work. Write the exact survey question with the client so it is neutral and not leading, and agree on four to six people of varied closeness to ask, in person or by text. Predict the answers before the survey goes out and write them down; the gap between prediction and result is the work. Clients sometimes ask only the people who will agree with them, so build the list together. Debrief on what the answers mean for the belief, not just whether they were nice.', '[{"id": "f0", "type": "textarea", "label": "The belief I am testing"}, {"id": "f1", "type": "textarea", "label": "The exact question I will ask (neutral, not leading)"}, {"id": "f2", "type": "textarea", "label": "Who I will ask, and how"}, {"id": "f3", "type": "textarea", "label": "My prediction of what each person will say"}, {"id": "f4", "type": "textarea", "label": "What each person actually said"}, {"id": "f5", "type": "textarea", "label": "How much I believe the original belief now, 0 to 100, and why"}]'::jsonb, array['behavioral experiment', 'core CBT', 'evidence']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('five-part-model-map', 'Five-Part Model Map', 'cbt'::resource_kind, 'A map of one recent situation into thoughts, emotions, body sensations and behavior, with arrows between them.', 'Use it to show a client how the parts of a hard moment feed each other.', array['Adults', 'Teens']::text[], '30 minutes', 'The classic first-session map, sometimes drawn as a hot cross bun. Take one specific recent moment, not a general problem, and fill the four parts with the client''s own words, then draw the arrows: the thought that tightened the chest, the tightness that confirmed the thought, the leaving early that kept the belief alive. Clients tend to put thoughts in the emotion box, so slow down and separate them. The map should end with the client seeing at least one arrow they could interrupt, which sets up every later tool.', '[{"id": "f0", "type": "textarea", "label": "The situation, in one or two sentences"}, {"id": "f1", "type": "textarea", "label": "What went through my mind"}, {"id": "f2", "type": "textarea", "label": "What I felt (emotions, one word each)"}, {"id": "f3", "type": "textarea", "label": "What I noticed in my body"}, {"id": "f4", "type": "textarea", "label": "What I did or stopped doing"}, {"id": "f5", "type": "textarea", "label": "The arrows: which part set off which"}, {"id": "f6", "type": "textarea", "label": "The one link I could try to change first"}]'::jsonb, array['formulation', 'core CBT', 'psychoeducation']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('hindsight-bias-check', 'Hindsight Bias Check', 'cbt'::resource_kind, 'A worksheet that separates what a client knew at the time of a decision from what they know now.', 'Use it to loosen the I-should-have-known thoughts that fuel self-blame after a bad outcome.', array['Adults', 'Teens']::text[], '30 minutes', 'For regret and self-blame after a decision that turned out badly: the missed warning sign in a relationship, the investment, the medical choice for a parent. Draw a line down the page and on the left list only what the client actually knew and could reasonably have known at the time; on the right, what they learned afterward. Clients smuggle hindsight onto the left side, so challenge each item with when exactly they learned it. Then ask what a careful person with only the left column would have decided. Keep this out of trauma material, which needs pacing first.', '[{"id": "f0", "type": "textarea", "label": "The decision I keep judging myself for"}, {"id": "f1", "type": "textarea", "label": "What I actually knew at the time"}, {"id": "f2", "type": "textarea", "label": "What I only learned afterward"}, {"id": "f3", "type": "textarea", "label": "What a careful person with only the first list would have done"}, {"id": "f4", "type": "textarea", "label": "The I-should-have-known thought, and a fairer version"}, {"id": "f5", "type": "textarea", "label": "What I would want to do differently with what I know now"}]'::jsonb, array['thinking traps', 'self-blame', 'core CBT']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('historical-test-of-a-core-belief', 'Historical Test of a Core Belief', 'cbt'::resource_kind, 'A decade-by-decade review of the evidence for and against a core belief across the client''s life.', 'Use it to show a client that a lifelong belief has always had evidence against it too.', array['Adults']::text[], 'Full session', 'Best after a downward arrow has surfaced a belief such as I am unlovable or I am a failure. Split the client''s life into stretches, early childhood, school years, teens, twenties and so on, and for each ask for evidence that seemed to support the belief and evidence that did not fit it. The against column fills slowly at first; prompt for small, ordinary things, a teacher who liked them, a friend who stayed. Finish by rewriting the belief in light of the whole record. Expect emotion in the early stretches and give it room.', '[{"id": "f0", "type": "textarea", "label": "The belief I am testing, in my own words"}, {"id": "f1", "type": "textarea", "label": "Childhood: what seemed to support it, and what did not fit"}, {"id": "f2", "type": "textarea", "label": "School years: what seemed to support it, and what did not fit"}, {"id": "f3", "type": "textarea", "label": "Teens and early twenties: what seemed to support it, and what did not fit"}, {"id": "f4", "type": "textarea", "label": "The years since: what seemed to support it, and what did not fit"}, {"id": "f5", "type": "textarea", "label": "Reading the whole record, a fairer version of the belief"}, {"id": "f6", "type": "textarea", "label": "How much I believe the old version now, 0 to 100"}]'::jsonb, array['core beliefs', 'evidence', 'belief change']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('overgeneralization-exception-finder', 'Overgeneralization Exception Finder', 'cbt'::resource_kind, 'A sheet that catches always-and-never thoughts and hunts for the exceptions that disprove them.', 'Use it to shrink one bad event back to one bad event.', array['Adults', 'Teens']::text[], '20 minutes', 'Teach the client to listen for always, never, everyone, nothing and every time, then pull one such thought from the week. Ask for a count: how many times, out of how many chances. Then hunt for exceptions, even one, from the last month and the last year. The thought usually survives as a milder, true version, I have been late twice this month, rather than vanishing. Teens take to this quickly when the exceptions are concrete. Pair it with a thought record once the client can spot the words on their own.', '[{"id": "f0", "type": "textarea", "label": "The always or never thought, exactly as it sounded"}, {"id": "f1", "type": "textarea", "label": "What actually happened this time"}, {"id": "f2", "type": "textarea", "label": "The count: how often has this really happened, out of how many chances?"}, {"id": "f3", "type": "textarea", "label": "Exceptions I can find from the last month"}, {"id": "f4", "type": "textarea", "label": "Exceptions I can find from the last year"}, {"id": "f5", "type": "textarea", "label": "The milder, true version of the thought"}]'::jsonb, array['thinking traps', 'evidence', 'core CBT']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('two-scales-metaphor-sheet', 'Two Scales Metaphor Sheet', 'act'::resource_kind, 'A worksheet on the two scales: the anxiety dial the client cannot control and the willingness dial they can.', 'Use it to move a client from trying to turn down anxiety to turning up willingness.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw two dials from 0 to 10. The first is how much anxiety or discomfort is present; the client has spent years trying to turn it down and it has not worked. The second is willingness, how open they are to having the discomfort while doing what matters, and that dial is in their hands. Walk through a recent situation and rate both. The insight lands when the client sees that with willingness at zero, anxiety is stuck at the top. Watch for the client treating willingness as a trick to lower anxiety; if the point is still to get rid of it, the dial is at zero.', '[{"id": "f0", "type": "textarea", "label": "A recent moment I tried hard to turn the anxiety down"}, {"id": "f1", "type": "textarea", "label": "Where the anxiety dial was, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "Where my willingness dial was, 0 to 10, and what that looked like"}, {"id": "f3", "type": "textarea", "label": "What I was trying to do or protect in that moment"}, {"id": "f4", "type": "textarea", "label": "What turning willingness up one notch would look like next time"}, {"id": "f5", "type": "textarea", "label": "What I notice about the anxiety dial when I stop fighting it"}]'::jsonb, array['willingness', 'metaphor', 'core ACT', 'acceptance']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('pliance-versus-tracking-sort', 'Pliance Versus Tracking Sort', 'act'::resource_kind, 'A sort of the client''s rules into the ones kept for approval and the ones kept because they work.', 'Use it to show a client which of their rules are about pleasing others rather than living well.', array['Adults', 'Teens']::text[], '30 minutes', 'Explain the two kinds of rule-following in plain words: pliance is doing a thing because someone would approve or disapprove, tracking is doing it because of what actually happens when you do. List the rules the client lives by, then sort each by asking what would happen if nobody ever found out. Rules kept purely for approval are the ones that tend to run a life off course. This is not about dropping every rule; some pliance keeps a job. The aim is to notice, then choose on workability. Teens with heavy parental expectations get a lot from it.', '[{"id": "f0", "type": "textarea", "label": "Rules I follow most days, written as always or never"}, {"id": "f1", "type": "textarea", "label": "For each one: if no one would ever know, would I still do it?"}, {"id": "f2", "type": "textarea", "label": "The rules I keep mainly for someone''s approval"}, {"id": "f3", "type": "textarea", "label": "The rules I keep because of what actually happens when I follow them"}, {"id": "f4", "type": "textarea", "label": "One approval rule that is costing me, and what it costs"}, {"id": "f5", "type": "textarea", "label": "What I would do with that rule if I chose on workability alone"}]'::jsonb, array['workability', 'defusion', 'core ACT']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('carry-the-keys-practice', 'Carry the Keys Practice', 'act'::resource_kind, 'A pocket practice in which a set of keys stands for the thoughts a client carries while still going where they want.', 'Use it to show a client they can take a hard thought with them rather than wait for it to leave.', array['Adults', 'Teens']::text[], '15 minutes, then daily', 'Hand the client their own keys and ask them to let each key be one thought or feeling they wish would go away before they act. Then ask them to put the keys in a pocket and walk to the door, open it, come back. The keys came too, and the walking still happened. Assign it for the week: before a valued action they have been postponing, touch the keys, name what is on the ring, and go anyway. It is small and physical, which is why it sticks. Avoid turning it into a trick to make the thoughts lighter; the keys weigh what they weigh.', '[{"id": "f0", "type": "textarea", "label": "The thoughts and feelings on my key ring, one per key"}, {"id": "f1", "type": "textarea", "label": "The thing I keep waiting to do until they go away"}, {"id": "f2", "type": "textarea", "label": "What happened when I carried the keys to the door"}, {"id": "f3", "type": "textarea", "label": "This week: the action I took with the keys in my pocket"}, {"id": "f4", "type": "textarea", "label": "What the keys felt like during it, and after"}, {"id": "f5", "type": "textarea", "label": "What I would do tomorrow if I never had to wait for the ring to be empty"}]'::jsonb, array['willingness', 'committed action', 'metaphor', 'core ACT']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('swamp-crossing-metaphor', 'Swamp Crossing Metaphor', 'act'::resource_kind, 'A worksheet on the swamp between a client and the mountain they chose, and why wading in is not a detour.', 'Use it to reframe the discomfort of a valued step as part of the path, not a sign to turn back.', array['Adults', 'Teens']::text[], '25 minutes', 'Tell it simply: the client set out for a mountain that matters to them and found a swamp in the way. They did not choose the swamp, but they can choose to wade through it because of where it leads. Then make it concrete: name the mountain, the swamp, the mud they are already standing in and how far the other bank is. The client who has been trying to go around the swamp for years tends to recognize the detour as the thing that has kept them stuck. Return to the image whenever a valued step gets uncomfortable mid-week.', '[{"id": "f0", "type": "textarea", "label": "My mountain: what I am heading for, and why it matters"}, {"id": "f1", "type": "textarea", "label": "My swamp: the discomfort that sits between me and it"}, {"id": "f2", "type": "textarea", "label": "Ways I have tried to go around the swamp, and how long that has taken"}, {"id": "f3", "type": "textarea", "label": "What it costs me to keep looking for a dry route"}, {"id": "f4", "type": "textarea", "label": "The first step into the swamp I am willing to take this week"}, {"id": "f5", "type": "textarea", "label": "A reminder to myself for when the mud is deep"}]'::jsonb, array['willingness', 'committed action', 'metaphor', 'values']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('thoughts-as-pop-up-ads-practice', 'Thoughts as Pop-Up Ads Practice', 'act'::resource_kind, 'A defusion practice that treats intrusive, repetitive thoughts like ads a client can notice and scroll past.', 'Use it to give a client a light way to notice a sticky thought without closing the browser.', array['Adults', 'Teens']::text[], '15 minutes, then daily', 'Ask the client what their mind''s most frequent pop-up says, and have them write it as an ad, with a headline and a call to action: You will embarrass yourself. Click here to cancel. Naming the sales pitch is the defusion. Practice in session with a few recent thoughts, then assign noticing for the week: when the ad appears, read the headline silently, label it an ad, and continue what they were doing. Do not let it tip into mocking the thought, which is just another fight. Teens who live online get this instantly.', '[{"id": "f0", "type": "textarea", "label": "The pop-up my mind shows most often, written as an ad with a headline"}, {"id": "f1", "type": "textarea", "label": "What the ad wants me to do (its call to action)"}, {"id": "f2", "type": "textarea", "label": "What usually happens when I click"}, {"id": "f3", "type": "textarea", "label": "This week: times I noticed the ad and kept doing what I was doing"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the ad when I did not click"}, {"id": "f5", "type": "textarea", "label": "Other ads my mind runs, so I recognize them next time"}]'::jsonb, array['defusion', 'core ACT', 'metaphor']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('recovering-from-invalidation-sheet', 'Recovering From Invalidation Sheet', 'dbt'::resource_kind, 'A skills sheet for the hours after someone dismissed a client''s feelings, with check the facts and self-validation.', 'Use it to help a client steady themselves after being invalidated without retaliating or collapsing.', array['Adults', 'Teens']::text[], '25 minutes', 'For clients whose worst moments follow being told they are overreacting. Walk through a recent instance: what was said, what they felt, what the feeling made them want to do. Then run the skills in order. Check the facts on what was actually said and meant; self-validate the parts of their reaction that make sense; decide whether the relationship needs a DEAR MAN later or simply a note to self; and pick a distress tolerance skill for the next hour. The common trap is using self-validation to prove the other person wrong, so keep the two separate.', '[{"id": "f0", "type": "textarea", "label": "What was said or done that felt dismissing"}, {"id": "f1", "type": "textarea", "label": "What I felt, and how strongly, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "Check the facts: what was actually said, and what else it could have meant"}, {"id": "f3", "type": "textarea", "label": "The parts of my reaction that make sense given my history and the situation"}, {"id": "f4", "type": "textarea", "label": "What I will do for the next hour to get through it"}, {"id": "f5", "type": "textarea", "label": "Whether this needs a conversation later, and the one line I would open with"}]'::jsonb, array['validation', 'check the facts', 'core DBT', 'interpersonal effectiveness']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('missing-links-analysis', 'Missing Links Analysis', 'dbt'::resource_kind, 'A short analysis of why a planned behavior, like practicing a skill or doing homework, did not happen.', 'Use it to find exactly where a plan fell through instead of starting a new one.', array['Adults', 'Teens']::text[], '15 minutes', 'Run it in session the moment a client says they did not do the thing, and keep it curious. Four questions in order: did they know what was expected and when, were they willing to do it, did the thought to do it ever come at the time, and if it did, what got in the way. Stop at the first no and solve that link only; most missed homework fails at the third question, the thought never showed up, which calls for a reminder, not a motivation talk. Clients expect to be scolded, so the matter-of-fact tone is the intervention.', '[{"id": "f0", "type": "textarea", "label": "What I planned to do, and when"}, {"id": "f1", "type": "textarea", "label": "Did I know what was expected? If not, what was unclear?"}, {"id": "f2", "type": "textarea", "label": "Was I willing to do it? If not, what got in the way of willingness?"}, {"id": "f3", "type": "textarea", "label": "Did the thought to do it come to mind at the time? If not, what would have reminded me?"}, {"id": "f4", "type": "textarea", "label": "If the thought came, what stopped me then?"}, {"id": "f5", "type": "textarea", "label": "The one link I will fix, and how"}]'::jsonb, array['core DBT', 'monitoring', 'problem solving']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('loving-kindness-practice-sheet', 'Loving Kindness Practice Sheet', 'dbt'::resource_kind, 'A mindfulness practice that sends the same few kind wishes to an easy person, oneself, and a hard person.', 'Use it to build a client''s capacity for warmth toward themselves and others, one short practice at a time.', array['Adults', 'Teens']::text[], '10 minutes daily for two weeks', 'Choose three or four phrases with the client in their own words: may you be safe, may you be at ease, whatever rings true. The order matters: start with someone easy to wish well, a pet counts, then the client themselves, then a neutral person, and only after some days a person they struggle with. Clients who are harsh on themselves often cannot say the phrases to themselves at first; let them say them to the easy person and notice the difference, and treat that gap as information rather than failure. Keep sessions short and the log honest.', '[{"id": "f0", "type": "textarea", "label": "My phrases, in my own words"}, {"id": "f1", "type": "textarea", "label": "The easy person I begin with"}, {"id": "f2", "type": "textarea", "label": "What it was like to say the phrases to them"}, {"id": "f3", "type": "textarea", "label": "What it was like to say them to myself"}, {"id": "f4", "type": "textarea", "label": "The neutral and the hard person I will add, and when"}, {"id": "f5", "type": "textarea", "label": "What I noticed over two weeks, in the practice and outside it"}]'::jsonb, array['core DBT', 'mindfulness', 'self-compassion']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('self-reinforcement-schedule', 'Self-Reinforcement Schedule', 'dbt'::resource_kind, 'A plan for rewarding a new behavior right after it happens, so it is more likely to happen again.', 'Use it to help a client make a wanted behavior stick with immediate, honest reinforcement.', array['Adults', 'Teens']::text[], '20 minutes to plan, then one week', 'DBT behavior change skills applied to the client''s own habit. Pick one behavior they want more of, small enough to happen daily, then choose a reinforcer that is immediate, available and actually pleasant to them, not a reward they think they should like. The timing is the lesson: within minutes, not at the end of the week. Many clients will only list punishments for failing; redirect to what follows success. Check that the reinforcer is not the very thing they are trying to cut back on. Review the week''s log for whether the behavior rose.', '[{"id": "f0", "type": "textarea", "label": "The behavior I want to see more of, small enough to do daily"}, {"id": "f1", "type": "textarea", "label": "What usually follows it right now (often nothing)"}, {"id": "f2", "type": "textarea", "label": "Something I genuinely enjoy that I can give myself within minutes of doing it"}, {"id": "f3", "type": "textarea", "label": "A larger reinforcer for a full week of it"}, {"id": "f4", "type": "textarea", "label": "This week''s log: each time I did it, and what followed"}, {"id": "f5", "type": "textarea", "label": "Did the behavior happen more often? What would I adjust?"}]'::jsonb, array['core DBT', 'habits', 'behavioral']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('asking-intensity-dime-check', 'Asking Intensity Dime Check', 'dbt'::resource_kind, 'A sheet that weighs ten factors to decide how firmly to ask for something or how firmly to say no.', 'Use it to help a client match the strength of an ask or a refusal to the situation.', array['Adults', 'Teens']::text[], '20 minutes', 'The dime game from interpersonal effectiveness. Before the client asks or refuses, walk the ten factors: their capability and the other person''s, timing, whether they have done their homework, authority, the relationship, the long-term goal, give and take, and self-respect. Each factor nudges the intensity up or down. Add them up to land somewhere between hinting and insisting, or between a soft maybe and a firm no. Clients who always ask at a whisper or always at a shout find the middle settings here. Pair it with DEAR MAN once the intensity is chosen.', '[{"id": "f0", "type": "textarea", "label": "What I want to ask for, or what I want to say no to"}, {"id": "f1", "type": "textarea", "label": "Can they give it, and can I handle it? Is this the right time?"}, {"id": "f2", "type": "textarea", "label": "Have I done my homework, and do I have the standing to ask?"}, {"id": "f3", "type": "textarea", "label": "What does this relationship, and my long-term goal with this person, say about how hard to push?"}, {"id": "f4", "type": "textarea", "label": "Have I been giving as well as taking? What does my self-respect say?"}, {"id": "f5", "type": "textarea", "label": "My intensity, 1 to 10, and the words I will use at that level"}]'::jsonb, array['interpersonal effectiveness', 'core DBT', 'DEAR MAN', 'assertiveness']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('accepting-influence-practice', 'Accepting Influence Practice', 'couples'::resource_kind, 'Each partner finds one recent decision where the other''s view was brushed aside and practices letting it move them.', 'Use it to help a couple notice when one partner''s input is not landing and practice yielding.', array['Couples']::text[], '40 minutes', 'From the Gottman work on accepting influence, which is about letting a partner''s opinion change what you do, not winning or losing. Ask each partner for a recent small decision, a purchase, a weekend plan, where the other''s view got waved off. The partner who waved it off restates the other''s view until the other says yes, that is it, then names one way they could let it change the outcome. Keep the examples small; big gridlocked topics belong elsewhere. Watch for the partner who yields on everything, which is a different problem, and name it.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a recent decision where my view did not seem to count"}, {"id": "f1", "type": "textarea", "label": "Partner B: that view in my own words, until Partner A agrees I have it"}, {"id": "f2", "type": "textarea", "label": "Partner B: one way I could let it change what we do"}, {"id": "f3", "type": "textarea", "label": "Partner B: a recent decision where my view did not seem to count"}, {"id": "f4", "type": "textarea", "label": "Partner A: that view in my own words, until Partner B agrees I have it"}, {"id": "f5", "type": "textarea", "label": "Partner A: one way I could let it change what we do"}, {"id": "f6", "type": "textarea", "label": "Both: how it felt to be taken into account, and what we will watch for this week"}]'::jsonb, array['Gottman', 'couples', 'decisions', 'communication']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('holiday-hosting-plan', 'Holiday Hosting Plan', 'couples'::resource_kind, 'A planner for a couple hosting family, covering who comes, who does what, and the signal for stepping away.', 'Use it to get a couple through a hosted holiday as a team rather than a pair of exhausted referees.', array['Couples']::text[], '45 minutes', 'Run it several weeks ahead. Partners first write separately what they want from the day and what they dread, then compare; the dread list is where the useful planning lives. Settle the guest list and the length of stay together, divide the visible and invisible jobs, and agree on a private signal either can use that means I need ten minutes. Decide in advance how each partner will handle their own family''s hardest member, so the other is not left to do it. The repeat argument is one partner volunteering the other, so flag it before it happens.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I want from the holiday, and what I dread"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I want from the holiday, and what I dread"}, {"id": "f2", "type": "textarea", "label": "Both: who is coming, and for how long"}, {"id": "f3", "type": "textarea", "label": "Both: the jobs, visible and invisible, and who owns each"}, {"id": "f4", "type": "textarea", "label": "Partner A: how I will handle the hardest person on my side"}, {"id": "f5", "type": "textarea", "label": "Partner B: how I will handle the hardest person on my side"}, {"id": "f6", "type": "textarea", "label": "Both: our private signal for needing a break, and what happens when it is given"}]'::jsonb, array['couples', 'planning', 'family', 'boundaries']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('vacation-expectations-alignment-sheet', 'Vacation Expectations Alignment Sheet', 'couples'::resource_kind, 'Partners write what a good trip looks like to each of them before booking, then design one that fits both.', 'Use it to head off the vacation fight before the suitcase is open.', array['Couples']::text[], '30 minutes', 'Couples rarely say out loud that one of them wants a packed itinerary and the other wants a chair and a book, and they discover it on day two. Have each partner describe their ideal day of the trip separately, including pace, spending, alone time, and how much phone and work is allowed, then compare. Build the trip from the overlap, and give each partner one protected day or half-day that is theirs. Agree on how money decisions get made on the road. Review after the trip; the debrief is where the next trip gets better.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my ideal day on this trip, from waking to sleeping"}, {"id": "f1", "type": "textarea", "label": "Partner B: my ideal day on this trip, from waking to sleeping"}, {"id": "f2", "type": "textarea", "label": "Both: where our ideal days overlap"}, {"id": "f3", "type": "textarea", "label": "Both: the one protected day or half-day each of us gets"}, {"id": "f4", "type": "textarea", "label": "Both: how we will handle spending, phones and work while away"}, {"id": "f5", "type": "textarea", "label": "After the trip: what worked, and what we will change next time"}]'::jsonb, array['couples', 'planning', 'communication', 'needs']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('alone-time-and-together-time-ledger', 'Alone Time and Together Time Ledger', 'couples'::resource_kind, 'A one-week ledger of each partner''s solitude and shared time, followed by a negotiation of what each needs.', 'Use it to turn the you-are-never-around fight into numbers both partners can work with.', array['Couples']::text[], 'One week, then 30 minutes', 'For the couple where one feels smothered and the other feels abandoned. Each partner keeps a rough tally for a week of hours alone, hours together but on separate screens, and hours actually together. Clients are regularly surprised by the parallel screen hours, which both partners had been counting as togetherness or as alone time depending on which one they wanted more of. Then each names the amount of each kind they need, and the couple negotiates a week that comes closer for both. Schedule the alone time too, so it stops being stolen.', '[{"id": "f0", "type": "textarea", "label": "Partner A: this week''s hours alone, side by side on screens, and truly together"}, {"id": "f1", "type": "textarea", "label": "Partner B: this week''s hours alone, side by side on screens, and truly together"}, {"id": "f2", "type": "textarea", "label": "Partner A: how much of each I need in a normal week"}, {"id": "f3", "type": "textarea", "label": "Partner B: how much of each I need in a normal week"}, {"id": "f4", "type": "textarea", "label": "Both: what the ledger showed us that we did not expect"}, {"id": "f5", "type": "textarea", "label": "Both: next week''s plan for alone time and together time, written on the calendar"}]'::jsonb, array['couples', 'needs', 'boundaries', 'connection']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('overfunctioning-and-underfunctioning-map', 'Overfunctioning and Underfunctioning Map', 'couples'::resource_kind, 'Partners map the areas where one does too much and the other has gone quiet, and plan one swap.', 'Use it to interrupt the pattern where one partner''s competence and the other''s retreat keep each other going.', array['Couples']::text[], '45 minutes', 'Lay out the life areas, money, kids, housework, social plans, health, extended family, and have each partner mark where they overfunction, where they underfunction, and where it is shared. The overfunctioning partner is usually exhausted and resentful, the underfunctioning one usually feels incompetent and criticized, and each blames the other for the pattern. Keep the frame circular: his stepping back invites her stepping in, which invites his stepping back. Pick one area to swap this month, and coach the overfunctioner on tolerating it being done differently.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the areas where I do most of it, and where I have gone quiet"}, {"id": "f1", "type": "textarea", "label": "Partner B: the areas where I do most of it, and where I have gone quiet"}, {"id": "f2", "type": "textarea", "label": "Partner A: what it is like to be on my side of the pattern"}, {"id": "f3", "type": "textarea", "label": "Partner B: what it is like to be on my side of the pattern"}, {"id": "f4", "type": "textarea", "label": "Both: how each of us keeps the other in place"}, {"id": "f5", "type": "textarea", "label": "Both: the one area we will swap this month, and what done differently is allowed to look like"}]'::jsonb, array['couples', 'pattern', 'fairness']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('brave-voice-megaphone-craft', 'Brave Voice Megaphone Craft', 'kids'::resource_kind, 'A child decorates a paper megaphone and practices saying what they need in a big, clear voice while the parent listens and answers.', 'Use it to give a quiet child a playful way to ask for help and be heard.', array['Children']::text[], '30 minutes', 'Roll and tape a sheet of paper into a cone and let the child decorate it. Then run three rounds: the child says a small need through it (a drink, a turn, help with a zipper), then a feeling, then something harder they have been holding back. The parent''s job is to stop, turn and answer in words, never to tease about the volume. Children who whisper usually need the parent to kneel and wait rather than prompt. If a child uses the megaphone to disclose harm, follow your reporting duties and tell the child they did the right thing by saying it.', '[{"id": "f0", "type": "textarea", "label": "What I need help with at home"}, {"id": "f1", "type": "textarea", "label": "A feeling I want my grown-up to know about"}, {"id": "f2", "type": "textarea", "label": "Something that is hard to say in a quiet voice"}, {"id": "f3", "type": "textarea", "label": "What my grown-up did when I said it through the megaphone"}, {"id": "f4", "type": "textarea", "label": "Where I will keep my megaphone"}]'::jsonb, array['children', 'communication', 'assertiveness', 'art']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('two-homes-suitcase-craft', 'Two Homes Suitcase Craft', 'kids'::resource_kind, 'A child whose parents live in two homes decorates a paper suitcase with what travels between them, including feelings.', 'Help a child name what moves between two homes and what stays steady in both.', array['Children']::text[], '40 minutes', 'Fold a sheet of card into a suitcase with a handle and let the child draw or glue in three kinds of things: objects that go back and forth, feelings that come along, and things that are the same in both homes (a bedtime story, a pet''s photo, a rule). Run it with one parent at a time and brief that parent first: they describe their own home only and never ask what happens at the other one. Watch for a child packing worries about a parent being alone; that is material for the parents, not the child. If a child discloses harm in either home, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Things that travel with me between my homes"}, {"id": "f1", "type": "textarea", "label": "A feeling that comes along in the suitcase"}, {"id": "f2", "type": "textarea", "label": "Things that are the same in both my homes"}, {"id": "f3", "type": "textarea", "label": "Something that is hard about changeover day"}, {"id": "f4", "type": "textarea", "label": "Something that would make changeover day easier"}]'::jsonb, array['children', 'family', 'transitions', 'art']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('doctor-visit-comic-strip', 'Doctor Visit Comic Strip', 'kids'::resource_kind, 'A child draws a four-panel comic of an upcoming medical visit, from the waiting room to the snack afterward, with the parent in it.', 'Use it to make a shot or checkup predictable for a child who dreads it.', array['Children']::text[], '30 minutes', 'Fold a page into four panels: arriving, waiting, the part the child dreads, and the walk out. The child draws each one with the parent in it doing a specific job (holding a hand, counting, reading aloud). Ask what the child wants the parent to say during the hard panel and write it in a speech bubble; parents tend to promise it will not hurt, which costs them trust, so coach honest words like a pinch that ends. Reread the comic the night before and bring it along. If the dread is about a particular adult rather than the procedure, ask more and follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Panel one: how we get there and who comes with me"}, {"id": "f1", "type": "textarea", "label": "Panel two: what I do in the waiting room"}, {"id": "f2", "type": "textarea", "label": "Panel three: the hard part, and what my grown-up says and does"}, {"id": "f3", "type": "textarea", "label": "Panel four: what happens right after"}, {"id": "f4", "type": "textarea", "label": "A question I want to ask the doctor or nurse"}]'::jsonb, array['children', 'medical', 'coping skills', 'art']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('screen-off-countdown-rocket-craft', 'Screen-Off Countdown Rocket Craft', 'kids'::resource_kind, 'A child builds a paper rocket with a five-minute countdown that ends screen time, and the parent flies it instead of announcing.', 'Use it to end screen time without a fight by making the countdown visible and the child the pilot.', array['Children']::text[], '25 minutes to make, then nightly', 'Make a rocket from a paper tube with five numbered windows the child covers one at a time as the minutes pass, and a launch door the device goes behind. The parent starts the countdown at window one, calls the numbers at the same pace every night and keeps a neutral face at launch; the first nights bring a protest at window two, and the rocket wins only if the parent neither argues nor adds minutes. Praise the landing, not the obedience, and draw what the child flies toward on the landing pad. If what a child says about what they watch raises concern, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "What I am watching or playing when the rocket starts"}, {"id": "f1", "type": "textarea", "label": "What I do at each window as the countdown goes"}, {"id": "f2", "type": "textarea", "label": "Where the screen lands at launch"}, {"id": "f3", "type": "textarea", "label": "What I fly toward after the screen is off"}, {"id": "f4", "type": "textarea", "label": "How launch went tonight, and what my grown-up said"}]'::jsonb, array['children', 'screen time', 'transitions', 'routines']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('feelings-orchestra-instrument-craft', 'Feelings Orchestra Instrument Craft', 'kids'::resource_kind, 'A child makes a shaker and a drum from kitchen things and plays each feeling loud or soft while the parent matches the volume.', 'Use it to give a child a way to show how big a feeling is without words.', array['Children']::text[], '30 minutes', 'Dry rice in a sealed jar makes a shaker and an upturned pot makes a drum. Ask the child to play a happy sound, a worried sound and a mad sound, then to play the same feeling small and then big. The parent copies the child''s volume exactly before offering a softer version, which teaches matching before settling; parents who go straight to shushing find the child plays louder. Use the instruments later in the week when the child cannot find words, the parent asking which instrument and how loud. If what the child plays or says points to harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "The instruments I made and what each one is for"}, {"id": "f1", "type": "textarea", "label": "How I play happy, worried and mad"}, {"id": "f2", "type": "textarea", "label": "What a small worry sounds like and what a big one sounds like"}, {"id": "f3", "type": "textarea", "label": "What my grown-up did when I played loud"}, {"id": "f4", "type": "textarea", "label": "A time this week I could use my instruments instead of words"}]'::jsonb, array['children', 'emotion identification', 'regulation', 'play']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('beat-the-clock-task-sprint', 'Beat the Clock Task Sprint', 'game'::resource_kind, 'A group or family game that races a five-minute timer on a task everyone has been putting off, then compares the dread with what happened.', 'Use it to show that starting is the hard part and that most dreaded tasks take less than the dread predicts.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'Rules: each player names one small task they have been avoiding (a drawer, an email), predicts how many minutes it needs and how bad it will feel, then everyone starts on the same whistle with a five-minute timer. Turns: at the buzzer each player reports done, partly done or not started, and anyone unfinished gets another five next round. Nobody scores for finishing; points go to the biggest gap between predicted dread and what happened. Debrief on the first thirty seconds and what each player will set a timer for at home. Keep the tasks small or the game proves the opposite.', '[{"id": "f0", "type": "textarea", "label": "The task I have been putting off"}, {"id": "f1", "type": "textarea", "label": "My prediction: how many minutes it will take and how bad it will feel"}, {"id": "f2", "type": "textarea", "label": "What actually happened by the buzzer"}, {"id": "f3", "type": "textarea", "label": "What the first thirty seconds were like"}, {"id": "f4", "type": "textarea", "label": "A task I will set a five-minute timer for this week"}]'::jsonb, array['group', 'task initiation', 'play', 'habits']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('headline-rewrite-game', 'Headline Rewrite Game', 'game'::resource_kind, 'Teams get a catastrophic headline about an ordinary mishap and race to write the fair version, then read both aloud.', 'Use it to practice catching exaggeration in a group that enjoys competition more than thought records.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Rules: the leader reads a headline the anxious or angry mind might write (Teen Forgets Homework, Future Ruined; Friend Takes an Hour to Reply, Friendship Over). Turns: each team has ninety seconds to write the fair headline a careful reporter would run, same facts and no spin, then both are read aloud and the room votes on which is closer to the truth. A point per fair headline and a bonus for the funniest exaggerated one, because naming the trick is the skill. After six rounds, players rewrite a headline their own mind ran this week. Debrief on the trick words that showed up most.', '[{"id": "f0", "type": "textarea", "label": "The exaggerated headline we were given"}, {"id": "f1", "type": "textarea", "label": "Our fair rewrite, same facts, no spin"}, {"id": "f2", "type": "textarea", "label": "The trick words that made the first one dramatic"}, {"id": "f3", "type": "textarea", "label": "A headline my own mind ran this week"}, {"id": "f4", "type": "textarea", "label": "My fair rewrite of it"}]'::jsonb, array['group', 'thinking traps', 'play']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('body-language-guess-game', 'Body Language Guess Game', 'game'::resource_kind, 'Players show a feeling using only posture and hands, with faces covered, while the group guesses and then checks.', 'Use it to sharpen reading of body cues and to show how often a guess about someone is wrong.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Rules: the player draws a feeling card, holds a sheet of paper in front of their face, and shows the feeling with shoulders, hands and stance alone for ten seconds. Turns: the group writes a guess, then the player reveals the card and says how they showed it. A point for every correct guess, and a point to the player if nobody got it. Debrief on which cues were read well, which feelings looked alike from the neck down (bored and sad), and what that means for reading a friend''s mood across a room. For clients sure they can tell what others think; the misses do the arguing.', '[{"id": "f0", "type": "textarea", "label": "The feeling I showed and how I used my body to show it"}, {"id": "f1", "type": "textarea", "label": "A feeling I guessed wrong, and what fooled me"}, {"id": "f2", "type": "textarea", "label": "Two feelings that looked alike from the neck down"}, {"id": "f3", "type": "textarea", "label": "A time I assumed what someone felt from their body and may have been wrong"}, {"id": "f4", "type": "textarea", "label": "What I will check before I trust a guess about someone"}]'::jsonb, array['group', 'emotion identification', 'social skills', 'play']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('role-reversal-argument-replay', 'Role Reversal Argument Replay', 'game'::resource_kind, 'Pairs replay a small recent disagreement with roles swapped, while the group watches for the line that could have turned it.', 'Use it to build perspective-taking by having each person argue the other side out loud.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Rules: a pair picks a low-stakes disagreement one of them had this week with someone not in the room (whose turn for the dishes, a canceled plan) and tells it in two sentences. Turns: they replay it for one minute with roles swapped, each playing the other person as fairly as they can, no caricatures. The audience raises a hand at any line that could have turned the argument, the pair freezes, and they try that line. Then new pairs. Debrief on what it felt like to speak the other side''s case and the line each person wishes they had said. Keep live conflicts between members out of the game.', '[{"id": "f0", "type": "textarea", "label": "The disagreement we replayed, in two sentences"}, {"id": "f1", "type": "textarea", "label": "What it was like to argue the other person''s side"}, {"id": "f2", "type": "textarea", "label": "The line the audience froze on"}, {"id": "f3", "type": "textarea", "label": "What I understand now about the other person''s position"}, {"id": "f4", "type": "textarea", "label": "A line I will try the next time this comes up"}]'::jsonb, array['group', 'perspective-taking', 'communication', 'play']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('broken-record-request-game', 'Broken Record Request Game', 'game'::resource_kind, 'A player makes a clear request and calmly repeats it while the others push back, derail and bargain for one minute.', 'Use it to practice holding a request steady under pressure without escalating or caving.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Rules: the player writes a one-sentence request (I need the car back by six) and says it. The others take turns with a tactic each: guilt, a joke, a counteroffer, a sulk. The player may acknowledge the tactic in a few words but must return to the same sentence in the same tone within ten seconds, for one minute. Turns rotate so everyone plays both roles. A point to the player for every return and a point to the group each time the player argues or gives in. Debrief on the hardest tactic and how the request sounded by the end. Watch for rising volume; the skill is the same tone.', '[{"id": "f0", "type": "textarea", "label": "My one-sentence request"}, {"id": "f1", "type": "textarea", "label": "The tactic that was hardest to stay steady against"}, {"id": "f2", "type": "textarea", "label": "What I said to acknowledge the pushback before returning to my request"}, {"id": "f3", "type": "textarea", "label": "How my voice changed over the minute, if it did"}, {"id": "f4", "type": "textarea", "label": "A real request I will hold steady this week"}]'::jsonb, array['group', 'assertiveness', 'interpersonal effectiveness', 'play']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('startle-recovery-log', 'Startle Recovery Log', 'worksheet'::resource_kind, 'A log of startle moments through the week, how long each took to settle and what helped the body come back down.', 'Use it to show a client their recovery time is shrinking and which settling moves work for their body.', array['Adults', 'Teens']::text[], 'One week', 'Startle is often the thing a client is most ashamed of, so frame the log as tracking recovery rather than jumpiness. Each entry records the trigger (a door, a touch from behind), the first body sign, the settling move used and the minutes until they felt ordinary again. Review it for which moves shorten the recovery and which triggers repeat often enough to plan for. Do not ask what the startle reminded them of; the log stays with the body and the present. If recovery times are stretching, or a startle is followed by hours on edge, slow the pace of other work and return to grounding.', '[{"id": "f0", "type": "textarea", "label": "What set off the startle (a sound, a touch, a movement)"}, {"id": "f1", "type": "textarea", "label": "The first thing I noticed in my body"}, {"id": "f2", "type": "textarea", "label": "What I did to settle"}, {"id": "f3", "type": "textarea", "label": "About how many minutes until I felt ordinary again"}, {"id": "f4", "type": "textarea", "label": "What I noticed over the week about which settling moves work"}]'::jsonb, array['PTSD and trauma', 'self-monitoring', 'grounding', 'regulation']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('self-trust-evidence-diary', 'Self-Trust Evidence Diary', 'cbt'::resource_kind, 'A daily evidence diary for the belief that one''s judgment can no longer be trusted, recording small decisions that went well enough.', 'Use it to loosen the belief that the client cannot read people or situations since the trauma.', array['Adults', 'Teens']::text[], 'Two weeks', 'Many clients after trauma hold a belief like I missed the signs, so I cannot trust my own judgment, and it stops them acting on their own read of anything. Write the belief in their words and rate it. Each day they record two or three ordinary judgments that turned out fine: crossing a street, reading a friend''s tone, choosing which line to join. The diary collects the evidence the belief filters out; it never revisits the original event or argues the client should have known. Re-rate the belief weekly. If entries dry up, walk through one day in detail and show how many judgments it contained.', '[{"id": "f0", "type": "textarea", "label": "The belief about my judgment, in my words, and how much I believe it from 0 to 100"}, {"id": "f1", "type": "textarea", "label": "A judgment I made today that turned out fine"}, {"id": "f2", "type": "textarea", "label": "Another one, however small"}, {"id": "f3", "type": "textarea", "label": "What the belief would have said about this day before I wrote it down"}, {"id": "f4", "type": "textarea", "label": "My rating of the belief after a week of entries"}]'::jsonb, array['PTSD and trauma', 'core CBT', 'core beliefs', 'evidence log']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('reminder-pop-up-ads-practice', 'Reminder Pop-Up Ads Practice', 'act'::resource_kind, 'A defusion practice that handles trauma reminders like pop-up ads: notice, name the ad, decline to click and return to the page.', 'Use it to give a client a light, repeatable way to let a reminder pass without following it.', array['Adults', 'Teens']::text[], '15 minutes, then as needed', 'Teach it on a mild reminder in session: when the image, phrase or body cue shows up, the client says there is the pop-up, gives it a short ad title (Danger Sale, Not Your Fault Clearance), and names the page they were on, meaning what they were doing a moment before, then puts attention back there. The humor is optional and some clients find it disrespectful to their history, so offer the plain version too. It never asks what the pop-up contains; the title is enough. If a reminder brings a full flashback rather than a pop-up, this is the wrong tool for that moment and grounding comes first.', '[{"id": "f0", "type": "textarea", "label": "A mild reminder I could practice on"}, {"id": "f1", "type": "textarea", "label": "The ad title I give it"}, {"id": "f2", "type": "textarea", "label": "The page I was on: what I was doing when it appeared"}, {"id": "f3", "type": "textarea", "label": "What happened when I declined to click and went back to the page"}, {"id": "f4", "type": "textarea", "label": "A reminder that is too big for this practice and needs grounding instead"}]'::jsonb, array['PTSD and trauma', 'defusion', 'core ACT', 'intrusive thoughts']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('dear-man-for-safety-requests', 'DEAR MAN for Safety Requests', 'dbt'::resource_kind, 'A DEAR MAN script for asking the people around a client for the practical things that help them feel safe, like a seat facing the door.', 'Use it to turn unspoken safety needs into clear, calm requests the client can make.', array['Adults', 'Teens']::text[], '30 minutes', 'Clients often arrange their safety silently (arriving early for the right seat, flinching from a hug) and feel ashamed when it fails. Pick one need and build the script: Describe the situation, Express how it affects them without the history, Assert the request, Reinforce what it gives the other person, stay Mindful of the ask, Appear confident, Negotiate a version that works for both. Rehearse aloud with you as the other person. The request names what helps now, never why; the client decides what to share about the past, and the script works without it. Start with someone likely to say yes.', '[{"id": "f0", "type": "textarea", "label": "The practical thing that helps me feel safe (a warning before touch, a seat facing the door, a lit path)"}, {"id": "f1", "type": "textarea", "label": "Describe: the situation where I need it"}, {"id": "f2", "type": "textarea", "label": "Express and Assert: how it affects me and what I am asking for"}, {"id": "f3", "type": "textarea", "label": "Reinforce: what saying yes gives the other person"}, {"id": "f4", "type": "textarea", "label": "Negotiate: a version I could accept if the full request does not work"}, {"id": "f5", "type": "textarea", "label": "Who I will ask first"}]'::jsonb, array['PTSD and trauma', 'DEAR MAN', 'interpersonal effectiveness', 'core DBT']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('startle-and-approach-agreement', 'Startle and Approach Agreement', 'couples'::resource_kind, 'Partners agree on how to enter a room, approach from behind, wake each other and touch unexpectedly so neither is caught off guard.', 'Use it to stop everyday startles from becoming a nightly source of hurt between partners.', array['Couples']::text[], '45 minutes', 'Partner A names the approaches that startle them (a hand on the shoulder from behind, being woken by touch, someone in a dark doorway) and what would work instead (a word from the door). Partner B says what it is like to be flinched away from and what they need in return, usually to hear it is not personal. Write the agreement as specific moves, not promises to be careful, and add how they will repair when one slips, since both will. Keep it on present-day logistics; Partner A decides what, if anything, to share about why. Revisit in a month and drop any rule no longer needed.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the approaches that startle me and what would work instead"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I need from my partner right after I startle"}, {"id": "f2", "type": "textarea", "label": "Partner B: what it is like for me when my partner flinches, and what helps me not take it personally"}, {"id": "f3", "type": "textarea", "label": "Partner B: the new moves I will make when entering, waking or touching"}, {"id": "f4", "type": "textarea", "label": "Both: how we will repair when one of us slips"}, {"id": "f5", "type": "textarea", "label": "Both: the date we will review this agreement"}]'::jsonb, array['PTSD and trauma', 'couples', 'safety', 'communication']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('overpreparation-cutback-experiment', 'Overpreparation Cutback Experiment', 'cbt'::resource_kind, 'A behavioral experiment that cuts preparation for a task by a set amount and compares the predicted outcome with what happened.', 'Use it to test whether hours of rehearsing, rereading or checking are protecting the client or feeding the worry.', array['Adults', 'Teens']::text[], 'One week', 'Pick one task the client overprepares for (a meeting, a text) and measure the current preparation in minutes or rereads. Set a cutback the client rates as uncomfortable but doable, often a third less, and write the prediction in detail: what will go wrong and how they will know. Run it, then compare. The trap is a quiet substitute, such as rehearsing in the shower instead of the written notes, so ask about it directly. Most find the outcome the same and the relief earlier; when it goes worse, check whether the task needed the preparation or anxiety read a normal hiccup as the disaster.', '[{"id": "f0", "type": "textarea", "label": "The task and how much I currently prepare for it (minutes, rereads, checks)"}, {"id": "f1", "type": "textarea", "label": "The cutback I will try"}, {"id": "f2", "type": "textarea", "label": "My prediction: what will go wrong and how I will know"}, {"id": "f3", "type": "textarea", "label": "What I did instead of preparing, and any sneaky substitutes"}, {"id": "f4", "type": "textarea", "label": "What actually happened and how it compares with my prediction"}, {"id": "f5", "type": "textarea", "label": "What I will try cutting back next"}]'::jsonb, array['anxiety', 'behavioral experiment', 'core CBT', 'safety behaviors']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('anxious-mind-sportscaster-practice', 'Anxious Mind Sportscaster Practice', 'act'::resource_kind, 'A defusion practice that casts the anxious mind as a sportscaster calling every possible fumble while the client keeps playing.', 'Use it to help a client hear the running commentary as commentary and stay in the game.', array['Adults', 'Teens']::text[], '20 minutes, then daily', 'Introduce the image in session: the mind in the booth narrating the play before it happens (and here comes the stumble, folks). Have the client do a small task while you call it in that voice, then swap so they do the calling, then both notice the game went on regardless. For homework they catch the commentary in the moment, say there goes the booth, and finish the play. It fails when it becomes a way to argue with the commentator, so check that the client lets the line run rather than correcting it. Pair it with a valued action the commentary usually talks them out of.', '[{"id": "f0", "type": "textarea", "label": "A situation where my mind starts commentating"}, {"id": "f1", "type": "textarea", "label": "Three lines the sportscaster typically calls"}, {"id": "f2", "type": "textarea", "label": "What I say to myself when I notice the booth has started"}, {"id": "f3", "type": "textarea", "label": "The play I kept making while the commentary ran"}, {"id": "f4", "type": "textarea", "label": "Something I would do more of if I let the booth talk without listening"}]'::jsonb, array['anxiety', 'defusion', 'core ACT', 'metaphor']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('avoidance-chain-analysis-sheet', 'Avoidance Chain Analysis Sheet', 'dbt'::resource_kind, 'A chain analysis of one avoided task, from vulnerability and prompting event through thoughts, body and urges to the moment of ducking out.', 'Use it to find the link in the chain where a skill could have kept the client in the situation.', array['Adults', 'Teens']::text[], '40 minutes', 'Choose one recent avoidance the client regrets (canceling a plan, leaving a store) and walk the chain in order: vulnerability factors that morning, the prompting event, each thought, body sensation and urge, the action, and the short and long consequences. Do not accept I just panicked as a link; there are usually five or six between the cue and the exit. Then mark two places a skill could have gone in (paced breathing at the body link, opposite action at the urge link) and write any repair owed. Clients skip the consequences column where the relief shows, so fill it in together.', '[{"id": "f0", "type": "textarea", "label": "What made me more vulnerable that day (sleep, caffeine, an earlier stress)"}, {"id": "f1", "type": "textarea", "label": "The prompting event: what happened right before"}, {"id": "f2", "type": "textarea", "label": "The links: each thought, body feeling and urge in the order they came"}, {"id": "f3", "type": "textarea", "label": "What I did and the relief it gave me"}, {"id": "f4", "type": "textarea", "label": "What it cost me afterward, including with other people"}, {"id": "f5", "type": "textarea", "label": "Two links where a skill could have gone in, and which skill"}, {"id": "f6", "type": "textarea", "label": "Any repair I owe"}]'::jsonb, array['anxiety', 'chain analysis', 'core DBT', 'avoidance']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('anxiety-led-decisions-review-for-two', 'Anxiety-Led Decisions Review for Two', 'couples'::resource_kind, 'Partners list the decisions the household has made around one partner''s anxiety, from trips not taken to routes always driven.', 'Use it to help a couple see how much of their shared life anxiety has quietly been deciding.', array['Couples']::text[], '45 minutes', 'Each partner separately lists decisions anxiety has shaped: the vacation not booked, the restaurant always chosen, the party left early. Compare the lists; the anxious partner usually sees fewer items and the other holds some unsaid resentment. Partner A says what each decision protected them from and what it cost; Partner B says what they went along with and what they miss. Then choose one small decision to make differently next month, with a plan for the anxious moments in it. Keep blame out: anxiety decided, and both let it. Watch for Partner B pushing for the biggest item.', '[{"id": "f0", "type": "textarea", "label": "Partner A: decisions I can see anxiety has made for us"}, {"id": "f1", "type": "textarea", "label": "Partner B: decisions I have gone along with because of my partner''s anxiety"}, {"id": "f2", "type": "textarea", "label": "Partner A: what those decisions protected me from, and what they cost me"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I miss, and what I have not said"}, {"id": "f4", "type": "textarea", "label": "Both: the one decision we will make differently this month"}, {"id": "f5", "type": "textarea", "label": "Both: our plan for the anxious moments in it"}]'::jsonb, array['anxiety', 'couples', 'decisions', 'avoidance']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('butterfly-belly-drawing-and-settle-plan', 'Butterfly Belly Drawing and Settle Plan', 'kids'::resource_kind, 'A child draws the butterflies in their tummy, gives them a size and a color, then draws what helps them land, with the parent as helper.', 'Use it to help a young child link the anxious feeling in their body to a settling move they can ask for.', array['Children']::text[], '30 minutes', 'Draw a body outline and ask the child where the fluttery feeling lives and to draw the butterflies there, with how many and what color when the feeling is small and when it is big. Then draw the things that help them land: a slow breath, a hand on the tummy, a hug, a quiet corner. The parent''s part is to ask which one the child wants when they say the butterflies are flying, and to do it rather than talk them out of the feeling. If the butterflies belong to a particular person or place and what the child says raises concern, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Where the butterflies live in my body"}, {"id": "f1", "type": "textarea", "label": "How many there are and what color when the feeling is small, and when it is big"}, {"id": "f2", "type": "textarea", "label": "Things that help my butterflies land"}, {"id": "f3", "type": "textarea", "label": "The one I will ask my grown-up for first"}, {"id": "f4", "type": "textarea", "label": "What my grown-up will do when I say the butterflies are flying"}]'::jsonb, array['anxiety', 'children', 'body awareness', 'art']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('stuck-record-hopeless-thought-practice', 'Stuck Record Hopeless Thought Practice', 'act'::resource_kind, 'A defusion practice that names a repeating hopeless thought as a stuck record and lets it play while the client does the next small thing.', 'Use it to loosen the grip of thoughts like nothing will change without arguing with them.', array['Adults', 'Teens']::text[], '20 minutes, in session', 'Complete it in session rather than as homework, because naming the hopeless thought can bring the mood with it. Ask for the line that plays most (nothing will ever change), have the client say it aloud a few times and notice the sameness, then label it: there is the stuck record again. The move is not to lift the needle but to let it play while they do one small valued thing in the room, such as opening the blinds. Ask directly whether the record ever says they would be better off dead; if so, stay with that first and plan together. Keep to the record''s title, never its lyrics.', '[{"id": "f0", "type": "textarea", "label": "The line my stuck record plays most"}, {"id": "f1", "type": "textarea", "label": "What I notice about it after saying it aloud a few times (how old it is, how samey)"}, {"id": "f2", "type": "textarea", "label": "The small thing I did in the room while it played"}, {"id": "f3", "type": "textarea", "label": "What the record did while I moved: louder, quieter, the same"}, {"id": "f4", "type": "textarea", "label": "If the record ever says I would be better off gone, who I will tell, and that I can call or text 988 any time"}]'::jsonb, array['depression', 'defusion', 'core ACT']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('reconnecting-after-going-quiet-give-plan', 'Reconnecting After Going Quiet GIVE Plan', 'dbt'::resource_kind, 'A GIVE skills plan for the first message or call to someone the client went quiet on during a low stretch.', 'Use it to make the first reach-out after withdrawal short, warm and survivable.', array['Adults', 'Teens']::text[], '30 minutes', 'Clients who withdrew for weeks often think the friend is angry and that any message must open with a long apology. Pick one person and draft it using GIVE: be Gentle (no self-attack in the message), act Interested (a question about them), Validate (acknowledge the gap without a speech) and use an Easy manner (light, one line of warmth). Keep it under four sentences; write the feared reply beside the one they would send a friend in the same spot. Rehearse sending it in session if the client is willing, since a second draft at home rarely gets sent. Agree what they will do while waiting.', '[{"id": "f0", "type": "textarea", "label": "The person I went quiet on and roughly how long it has been"}, {"id": "f1", "type": "textarea", "label": "Gentle: the message with every self-attack taken out"}, {"id": "f2", "type": "textarea", "label": "Interested: the question I will ask about them"}, {"id": "f3", "type": "textarea", "label": "Validate: how I will acknowledge the gap in one line"}, {"id": "f4", "type": "textarea", "label": "Easy manner: the final message, under four sentences"}, {"id": "f5", "type": "textarea", "label": "The reply I fear, and the reply I would send a friend who went quiet on me"}, {"id": "f6", "type": "textarea", "label": "What I will do with the first hour of waiting"}]'::jsonb, array['depression', 'GIVE', 'interpersonal effectiveness', 'connection']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('early-signs-watchlist-for-two', 'Early Signs Watchlist for Two', 'couples'::resource_kind, 'Partners write the early signs that a low stretch is starting, what each partner will do when they see them and when to call for help.', 'Use it to catch a dip early and give the supporting partner a job other than worrying.', array['Couples']::text[], 'Full session, in session', 'Complete it in session, not as homework, because the last prompts reach into crisis. Partner A, who has the low stretches, lists their own early signs (sleeping through the morning, a stopped group chat). Partner B adds the signs they notice first, which are often different and earlier. Agree the move for each stage: a question that is not how are you, a shared walk, a call to the clinician, and the signs that mean call or text 988 together. Write who says what, since partners who notice often say nothing for fear of making it worse. Keep the list short and revisit it after a stretch passes.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the early signs I notice in myself when a low stretch is starting"}, {"id": "f1", "type": "textarea", "label": "Partner B: the signs I notice first, and roughly how many days before my partner names it"}, {"id": "f2", "type": "textarea", "label": "Both: what Partner B will do and say at the first signs, and what Partner A wants them not to say"}, {"id": "f3", "type": "textarea", "label": "Both: the signs that mean we contact the clinician"}, {"id": "f4", "type": "textarea", "label": "Both: the signs that mean we call or text 988 together, and who makes the call"}, {"id": "f5", "type": "textarea", "label": "Both: how Partner A will tell Partner B when the watchlist is wrong"}]'::jsonb, array['depression', 'couples', 'support', 'safety']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('flashlight-in-the-cave-drawing', 'Flashlight in the Cave Drawing', 'kids'::resource_kind, 'A child draws a gray-day cave, then flashlight beams that light up small good things, with the parent holding the flashlight at bedtime.', 'Use it to give a child with low mood a daily way to find one or two good things without being told to cheer up.', array['Children']::text[], '30 minutes to make, then nightly', 'The child draws a cave with themselves inside on a gray day and colors it how the day feels. Then they draw a flashlight and three beams, and in each beam something small the day had: a warm sandwich, a dog they passed. At bedtime the parent holds a real flashlight, shines it on the drawing and asks what goes in the beams tonight, accepting anything offered and never arguing with an empty beam; an empty beam is information, not failure. If what a child says in the cave points to harm, or to wishing they were not here, ask more, follow your reporting duties and tell the parent that day.', '[{"id": "f0", "type": "textarea", "label": "My cave on a gray day, and what it looks like inside"}, {"id": "f1", "type": "textarea", "label": "Beam one: a small good thing today"}, {"id": "f2", "type": "textarea", "label": "Beam two: a person or animal who was good to be near"}, {"id": "f3", "type": "textarea", "label": "Beam three: something I did, even tiny"}, {"id": "f4", "type": "textarea", "label": "What my grown-up did with the flashlight tonight"}]'::jsonb, array['depression', 'children', 'art', 'strengths']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('dominoes-of-doing-game', 'Dominoes of Doing Game', 'game'::resource_kind, 'Players lay dominoes in a line, each one a tiny action that follows naturally from the last, then tip the first and watch momentum work.', 'Use it to show a group how one small action makes the next one easier on a low-energy day.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Rules: each player gets six paper dominoes and a start card naming a low-energy state (on the couch at two, still in bed at ten). Turns: each player lays one domino with a tiny action that could follow the last one for their start card (sit up, feet on floor, open the blinds); the group may challenge any step that is too big and send it back to be split. When every line has six, each player reads theirs aloud and tips the first domino. Debrief on which first domino felt possible on a real bad day and what each player''s own first domino will be this week. A line that reaches the shower wins.', '[{"id": "f0", "type": "textarea", "label": "My start card: where I am and what the energy is like"}, {"id": "f1", "type": "textarea", "label": "My six dominoes, in order, each one tiny"}, {"id": "f2", "type": "textarea", "label": "The step the group sent back to be split, and how I split it"}, {"id": "f3", "type": "textarea", "label": "The first domino that feels possible on a real bad day"}, {"id": "f4", "type": "textarea", "label": "My own first domino for this week, and when"}]'::jsonb, array['depression', 'behavioral activation', 'group', 'play']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('dear-man-for-workplace-accommodations', 'DEAR MAN for Workplace Accommodations', 'dbt'::resource_kind, 'A DEAR MAN script for asking a manager or instructor for a concrete adjustment such as written instructions or a quieter desk.', 'Help a client ask for one specific adjustment at work or school without apologizing or over-explaining.', array['Adults', 'Teens']::text[], '30 minutes', 'Pick one adjustment that would change the week, not a list. Clients with attention and working memory struggles tend to either never ask or ask in a rush of justification, so keep the Describe and Express lines to a sentence each and put the energy into a precise Assert: what, by when, in what form. Rehearse the Reinforce line until it sounds like a benefit to the other person, since that is usually what lands. Watch for the client disclosing more about their attention than they intended; they can name the need without naming a reason.', '[{"id": "f0", "type": "textarea", "label": "Describe: the situation in one factual sentence"}, {"id": "f1", "type": "textarea", "label": "Express: how it affects my work, in one sentence"}, {"id": "f2", "type": "textarea", "label": "Assert: the exact adjustment I am asking for"}, {"id": "f3", "type": "textarea", "label": "Reinforce: what this makes easier for them or the team"}, {"id": "f4", "type": "textarea", "label": "Mindful: the line I will repeat if the conversation drifts"}, {"id": "f5", "type": "textarea", "label": "Appear confident: how I will sit, look and sound"}, {"id": "f6", "type": "textarea", "label": "Negotiate: a smaller version I could accept"}, {"id": "f7", "type": "textarea", "label": "Who I will ask, where and when"}]'::jsonb, array['ADHD', 'DEAR MAN', 'interpersonal effectiveness']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('hyperfocus-and-feeling-unseen-conversation', 'Hyperfocus and Feeling Unseen Conversation', 'couples'::resource_kind, 'A guided conversation for a couple where one partner drops into hours of hyperfocus and the other is left feeling forgotten.', 'Use it to separate the pull of hyperfocus from the message the other partner reads into it.', array['Couples']::text[], '45 minutes', 'Start with the partner who hyperfocuses describing what the state is like from inside, including how little of the room registers, before the other partner says how the silence lands. The usual trap is the unseen partner hearing hyperfocus as a choice and the focused partner hearing hurt as an attack on the one thing they are good at. Have them agree on a signal that is not a tap on the shoulder, a fixed surfacing time with an alarm the focused partner sets themselves, and one short reconnecting gesture afterward. Keep the plan small enough to survive a bad week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what hyperfocus is like from inside, and what I do not notice"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I am afraid my partner thinks it means"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I tell myself when the hours go by"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I actually need when my partner surfaces"}, {"id": "f4", "type": "textarea", "label": "Our agreed signal that means come up for air"}, {"id": "f5", "type": "textarea", "label": "The alarm or surfacing time Partner A will set"}, {"id": "f6", "type": "textarea", "label": "The reconnecting gesture we will use afterward"}, {"id": "f7", "type": "textarea", "label": "How we will know the plan is working"}]'::jsonb, array['ADHD', 'couples', 'connection']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('homes-for-my-things-map-craft', 'Homes for My Things Map Craft', 'kids'::resource_kind, 'A child draws a map of their home and gives each often-lost item a labeled home, then does a nightly round-up with a parent.', 'Use it to turn lost shoes and backpacks into a drawn system the child built and can follow.', array['Children']::text[], '40 minutes', 'The child draws the rooms, then picks the five things that go missing most and draws a home for each, with a picture label the parent helps tape to the real spot. The parent''s job is the two-minute bedtime round-up, walking the map with the child and praising every item already home rather than hunting for the missing one. Do not let the parent redesign the homes; a child will use a system they chose and ignore a tidier one. If the child mentions being punished harshly for lost things or discloses anything that worries you, follow your mandated reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw your house with the rooms you use most"}, {"id": "f1", "type": "textarea", "label": "The five things that get lost the most"}, {"id": "f2", "type": "textarea", "label": "Draw a home for each thing and give it a name"}, {"id": "f3", "type": "textarea", "label": "What my parent and I say at round-up time"}, {"id": "f4", "type": "textarea", "label": "How many things were home tonight"}]'::jsonb, array['ADHD', 'children', 'routines', 'art']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('pass-the-instruction-game', 'Pass the Instruction Game', 'game'::resource_kind, 'A group game where each player repeats a multi-step instruction, adds one step, and carries it out, stretching working memory.', 'Use it to practice holding and acting on several steps while laughing at the drops.', array['Groups', 'Children', 'Teens']::text[], '25 minutes', 'The first player gives a two-step instruction such as touch the door then clap twice, the next player repeats it, does it, and adds a step, and so on round the circle. Rules: no writing, a player may ask for one repeat, and when the chain breaks the group cheers the length it reached and starts fresh. Play three rounds, then a round where players may use any trick they like, such as chunking, saying it aloud or acting it as they hear it, and notice what changes. Debrief on which tricks helped and where the same trick fits in homework or morning routines.', '[{"id": "f0", "type": "textarea", "label": "The longest chain our group reached"}, {"id": "f1", "type": "textarea", "label": "Where my memory tends to drop a step"}, {"id": "f2", "type": "textarea", "label": "A trick that helped me hold more steps"}, {"id": "f3", "type": "textarea", "label": "A real situation where I lose steps"}, {"id": "f4", "type": "textarea", "label": "The trick I will try there this week"}]'::jsonb, array['ADHD', 'group', 'play', 'skills']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('impulse-spending-pause-sheet', 'Impulse Spending Pause Sheet', 'worksheet'::resource_kind, 'A pause sheet filled in before any unplanned purchase, naming the pull, the cost in work hours and what the buy is for.', 'Use it to put a gap between the urge to buy and the click.', array['Adults', 'Teens']::text[], 'Ten minutes per purchase for two weeks', 'Ask the client to fill the sheet before buying anything they did not plan that morning, then wait a set time they choose, usually a day, before deciding. Converting the price into hours of their own work and naming what the purchase is really for, whether novelty, relief from boredom or a reward after a hard day, does most of the work. Clients with impulse struggles often skip the sheet when the pull is strongest, so keep the first version to three lines on their phone and expand later. Review the list in session for patterns in time of day and mood rather than scolding the misses.', '[{"id": "f0", "type": "textarea", "label": "What I want to buy and what it costs"}, {"id": "f1", "type": "textarea", "label": "How many hours of my work that is"}, {"id": "f2", "type": "textarea", "label": "What was happening just before the pull"}, {"id": "f3", "type": "textarea", "label": "What this purchase is really for"}, {"id": "f4", "type": "textarea", "label": "How long I will wait before deciding"}, {"id": "f5", "type": "textarea", "label": "What I decided, and how I felt the next day"}]'::jsonb, array['ADHD', 'self-monitoring', 'decisions', 'urges']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('if-a-lapse-happens-agreement', 'If a Lapse Happens Agreement', 'couples'::resource_kind, 'Partners agree in advance how a lapse in substance use will be told, heard and handled in the first day.', 'Use it to replace a feared conversation with a rehearsed one both partners already signed.', array['Couples']::text[], '45 minutes', 'Write this while things are steady, never in the week after a lapse. The partner in recovery names how they will tell their partner and what they will do in the first hour, such as calling a sponsor or a support line. The other partner names what they will say, what they will not do, such as searching bags or going silent for days, and what they need for themselves. Watch for the recovering partner promising it will never happen, which makes the agreement feel like an accusation; frame it as the plan every pilot files. Keep the agreement to one page and review it monthly.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I will tell you, and by when"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I will do in the first hour"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I need from you that day"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I will say when I hear it"}, {"id": "f4", "type": "textarea", "label": "Partner B: what I will not do"}, {"id": "f5", "type": "textarea", "label": "Partner B: who I will lean on for myself"}, {"id": "f6", "type": "textarea", "label": "What we will do together the next day"}, {"id": "f7", "type": "textarea", "label": "When we will review this agreement"}]'::jsonb, array['addiction', 'couples', 'relapse prevention']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('grown-up-jobs-and-kid-jobs-sort', 'Grown-Up Jobs and Kid Jobs Sort', 'kids'::resource_kind, 'A child draws job cards and sorts them into a grown-up jar and a kid jar, finding that fixing a parent''s substance use is not theirs.', 'Use it to lift the sense of responsibility a child carries for a parent''s substance use.', array['Children']::text[], '35 minutes', 'The child draws or dictates jobs on cards, such as making dinner, keeping everyone safe, helping a grown-up stop using, playing and telling a safe adult how I feel, then sorts them into two decorated jars. The sober caregiver sits beside the child and takes the grown-up cards into their own jar aloud. Talk about the behavior, someone''s substance use, never a label for the person. Children often slip a grown-up card into their own jar; ask about it gently rather than correcting. If the child describes being unsupervised or otherwise unsafe, follow your mandated reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw or write jobs that happen in my family"}, {"id": "f1", "type": "textarea", "label": "The jobs that belong in the grown-up jar"}, {"id": "f2", "type": "textarea", "label": "The jobs that belong in the kid jar"}, {"id": "f3", "type": "textarea", "label": "A job I was carrying that is not mine"}, {"id": "f4", "type": "textarea", "label": "A grown-up who will take that job now"}, {"id": "f5", "type": "textarea", "label": "A kid job I want to do more of"}]'::jsonb, array['addiction', 'children', 'family', 'play']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('halt-charades', 'HALT Charades', 'game'::resource_kind, 'A group game where players act out being hungry, angry, lonely or tired and the others guess the state and name a fix.', 'Use it to make the HALT check automatic before an urge gets a vote.', array['Groups', 'Adults', 'Teens']::text[], '30 minutes', 'Deal cards marked H, A, L or T, with a few scene cards such as after a long shift or alone on a Friday. On each turn a player acts the state without words while the group guesses; the guesser then names one thing that would meet that need within ten minutes, and the actor says whether it would work for them. Rules: no acting out substance use itself, pass any card you like, and the group claps for the guess and the fix equally. Debrief on which of the four states each person spots last in themselves and what their earliest sign of it is.', '[{"id": "f0", "type": "textarea", "label": "The HALT state I acted and how it felt to show it"}, {"id": "f1", "type": "textarea", "label": "The state I find hardest to spot in myself"}, {"id": "f2", "type": "textarea", "label": "My earliest sign of that state"}, {"id": "f3", "type": "textarea", "label": "A ten-minute fix the group named that I would really use"}, {"id": "f4", "type": "textarea", "label": "When I will run a HALT check this week"}]'::jsonb, array['addiction', 'urges', 'group', 'play']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('holiday-and-celebration-plan', 'Holiday and Celebration Plan', 'worksheet'::resource_kind, 'A planning sheet for a wedding, holiday or party where substance use is expected, covering arrival, drink in hand, exit and backup.', 'Use it to walk into a celebration with a plan instead of a hope.', array['Adults']::text[], '30 minutes', 'Fill it in at least a week before the event. Get specific on logistics: how the client arrives and leaves without depending on someone who may stay late, what will be in their hand all evening, the one-line reply to offers, and who they will text at a set time. The urge usually peaks at a predictable moment, such as the toast or the point where the sober guests go home, so have them name that moment and a planned move for it. Watch for clients planning to leave the second it gets hard, which can feel like failure; a planned early exit is a win if it is written here.', '[{"id": "f0", "type": "textarea", "label": "The event, the date and who will be there"}, {"id": "f1", "type": "textarea", "label": "How I will get there and how I will get home"}, {"id": "f2", "type": "textarea", "label": "What will be in my hand all evening"}, {"id": "f3", "type": "textarea", "label": "What I will say when someone offers"}, {"id": "f4", "type": "textarea", "label": "The moment the urge is likely to peak and my move for it"}, {"id": "f5", "type": "textarea", "label": "Who I will text, and at what time"}, {"id": "f6", "type": "textarea", "label": "My planned exit, and the line I will use"}, {"id": "f7", "type": "textarea", "label": "How I will mark getting through it"}]'::jsonb, array['addiction', 'planning', 'urges']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('after-a-slip-thought-record', 'After a Slip Thought Record', 'cbt'::resource_kind, 'A thought record for the hours after a slip, catching the all-or-nothing thoughts that turn one use into a run.', 'Use it to stop the thought I have blown it from deciding what happens next.', array['Adults', 'Teens']::text[], '20 minutes', 'The dangerous moment is not the slip but the thought right after it: I have blown it, the streak is gone, might as well keep going. Have the client record that thought while the slip is recent, rate how much they believed it, and look for the evidence on both sides, then write a reply that is accurate rather than cheerful, such as one use is one use and the next hour is still open. Rehearse it in session with a past slip first so the card exists before it is needed. Watch for shame turning the record into a confession; keep it on the thought, not the character.', '[{"id": "f0", "type": "textarea", "label": "What happened, in one factual line"}, {"id": "f1", "type": "textarea", "label": "The thought that came right after"}, {"id": "f2", "type": "textarea", "label": "How much I believed it, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "What that thought wanted me to do next"}, {"id": "f4", "type": "textarea", "label": "Evidence the thought is true"}, {"id": "f5", "type": "textarea", "label": "Evidence it is not the whole story"}, {"id": "f6", "type": "textarea", "label": "A more accurate thought, and how much I believe it"}, {"id": "f7", "type": "textarea", "label": "What I will do in the next hour"}]'::jsonb, array['addiction', 'thought record', 'thinking traps', 'relapse prevention']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('turtle-shell-calm-craft', 'Turtle Shell Calm Craft', 'kids'::resource_kind, 'A child builds a paper-plate turtle and learns its four steps: stop, go into the shell, breathe three times, come out with a plan.', 'Use it to give a young child a body routine for the moment anger hits.', array['Children']::text[], '35 minutes', 'Decorate the plate shell together and write or draw the four steps inside it. Practice the shell pose, arms wrapped and head down, with pretend scenarios before anyone is actually angry, since a child will not learn a new move mid-meltdown. The parent''s job is to practice the same pose and say the same four words at home, and to praise going into the shell even when the child comes out still cross. Watch for a parent using the turtle as a punishment corner; it is a pause the child chooses. If the child''s play or drawings suggest they are being hurt, follow your mandated reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Decorate your turtle and give it a name"}, {"id": "f1", "type": "textarea", "label": "The four turtle steps, in my words"}, {"id": "f2", "type": "textarea", "label": "Something that makes my turtle want to hide"}, {"id": "f3", "type": "textarea", "label": "What I will think about inside my shell"}, {"id": "f4", "type": "textarea", "label": "A plan my turtle could come out with"}, {"id": "f5", "type": "textarea", "label": "When my parent and I practiced the turtle"}]'::jsonb, array['anger management', 'children', 'play', 'regulation']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('shield-up-teasing-practice-game', 'Shield Up Teasing Practice Game', 'game'::resource_kind, 'A group game where one player holds a drawn shield and practices a cool reply to mild scripted teasing from cards.', 'Use it to rehearse staying level under provocation in a setting the player controls.', array['Groups', 'Teens', 'Children']::text[], '30 minutes', 'Write the teasing lines on cards before the game, all mild and generic, such as nice shoes or you always lose, and let the group veto any card. The shield player picks a cool-down move in advance, such as a slow breath, a flat so what, or walking to the agreed exit spot, and holds the shield while two players read cards; the player can say stop at any point and the round ends with applause. Rules: only card lines, never personal material, and every player gets a turn at the shield. Debrief on what the body did first and which move was easiest to use while being watched.', '[{"id": "f0", "type": "textarea", "label": "The cool-down move I chose before my turn"}, {"id": "f1", "type": "textarea", "label": "What my body did first when the teasing started"}, {"id": "f2", "type": "textarea", "label": "What was easiest about staying level"}, {"id": "f3", "type": "textarea", "label": "What was hardest"}, {"id": "f4", "type": "textarea", "label": "A real situation where my shield would help"}, {"id": "f5", "type": "textarea", "label": "The move I will use there"}]'::jsonb, array['anger management', 'group', 'play', 'regulation']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('driving-anger-log', 'Driving Anger Log', 'worksheet'::resource_kind, 'A log kept after drives, recording the trigger, the thought about the other driver, what the client did and what it risked.', 'Use it to make road anger visible before it costs a license or worse.', array['Adults']::text[], 'Five minutes after each drive for two weeks', 'Driving is where a lot of anger shows up unobserved, so this log is often the first honest record a client has of it. Ask them to fill it right after parking, not while driving, and to include the thought about the other driver, which is nearly always a mind-read about intent. Have them rate what they did on a scale from muttering to tailgating and note any passengers, since children in the back seat change the stakes. Review for the patterns that matter: time pressure, specific routes, hunger, or a particular kind of driver. Keep the honesty safe by never shaming the entries.', '[{"id": "f0", "type": "textarea", "label": "The drive, the time and who was in the car"}, {"id": "f1", "type": "textarea", "label": "What the other driver did"}, {"id": "f2", "type": "textarea", "label": "What I told myself about them"}, {"id": "f3", "type": "textarea", "label": "What I did, from muttering to something riskier"}, {"id": "f4", "type": "textarea", "label": "What it could have cost"}, {"id": "f5", "type": "textarea", "label": "What I was already carrying before I got in the car"}, {"id": "f6", "type": "textarea", "label": "One thing I will do differently on that route"}]'::jsonb, array['anger management', 'self-monitoring', 'triggers']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('quiet-voice-behavioral-experiment', 'Quiet Voice Behavioral Experiment', 'cbt'::resource_kind, 'A behavioral experiment testing the belief that nobody listens unless the client raises their voice.', 'Use it to test what actually happens when a point is made at normal volume.', array['Adults', 'Teens']::text[], 'One week', 'Most clients who shout hold a belief that volume is the only thing that gets results, and arguing with that belief rarely moves it. Instead, write the prediction in their words, such as if I say it quietly they will ignore me, pick two low-stakes situations this week, and have them make the same point at a normal volume while keeping the content firm. Record what the other person did within the next minute, since clients tend to count only immediate compliance. Debrief what the data says, including the cases where the quiet version did not work, and what shouting usually costs afterward.', '[{"id": "f0", "type": "textarea", "label": "The belief I hold about volume, in my words"}, {"id": "f1", "type": "textarea", "label": "My prediction for what happens if I say it quietly"}, {"id": "f2", "type": "textarea", "label": "How sure I am, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "Situation one: what I said, how I said it, what they did"}, {"id": "f4", "type": "textarea", "label": "Situation two: what I said, how I said it, what they did"}, {"id": "f5", "type": "textarea", "label": "What the results say about my prediction"}, {"id": "f6", "type": "textarea", "label": "What shouting usually costs me afterward"}, {"id": "f7", "type": "textarea", "label": "My updated belief, and how sure I am now"}]'::jsonb, array['anger management', 'behavioral experiment', 'core CBT']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('grievance-story-defusion-practice', 'Grievance Story Defusion Practice', 'act'::resource_kind, 'A defusion practice for the replayed story of who wronged the client, holding it as a story the mind tells rather than a verdict.', 'Use it to loosen the grip of a grievance the client keeps retelling.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client write the grievance exactly as the mind tells it, then give the story a title like a film and notice how often the mind replays it and what it does to their body and their day. The point is not to decide whether the story is true; many grievances are accurate and still cost the client their evenings. Practice prefixing the replay with here comes the story again, and ask what they would be doing with the next hour if the story were on in the background rather than center stage. Watch for the client hearing this as being told to forgive; defusion asks nothing of the other person.', '[{"id": "f0", "type": "textarea", "label": "The story my mind tells about what they did"}, {"id": "f1", "type": "textarea", "label": "The title I would give that story"}, {"id": "f2", "type": "textarea", "label": "How many times a day my mind replays it"}, {"id": "f3", "type": "textarea", "label": "What the replay does to my body and my evening"}, {"id": "f4", "type": "textarea", "label": "The line I will say when it starts: here comes the story again"}, {"id": "f5", "type": "textarea", "label": "What I would do with the next hour if the story were only background"}, {"id": "f6", "type": "textarea", "label": "Something I want to do this week that the story usually crowds out"}]'::jsonb, array['anger management', 'defusion', 'core ACT']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('deliberate-mistakes-drawing-game', 'Deliberate Mistakes Drawing Game', 'game'::resource_kind, 'A group drawing game where every player must leave a deliberate error in their picture and sit with the not-just-right feeling.', 'Use it to practice tolerating imperfection in a playful setting with others doing the same.', array['Groups', 'Teens', 'Children']::text[], '30 minutes', 'Each round the leader names a simple subject, such as a house or a cat, and a required mistake, such as one window crooked or the name misspelled, and players draw for two minutes. Rules: the mistake stays, no fixing, no starting over, and everyone rates their itch to correct it from 0 to 10 before the drawings go on the wall for the rest of the session. Players who feel no itch can up the stakes by signing the drawing. Debrief on what happened to the itch over twenty minutes and which mistakes were hardest to leave. The drawings can go home as reminders.', '[{"id": "f0", "type": "textarea", "label": "The mistake I had to leave in my drawing"}, {"id": "f1", "type": "textarea", "label": "My itch to fix it right after, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "My itch twenty minutes later"}, {"id": "f3", "type": "textarea", "label": "The mistake that was hardest to leave"}, {"id": "f4", "type": "textarea", "label": "What I noticed other players doing with their itch"}, {"id": "f5", "type": "textarea", "label": "A small deliberate mistake I could make at home this week"}]'::jsonb, array['OCD', 'uncertainty', 'group', 'play']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('confession-urge-log', 'Confession Urge Log', 'worksheet'::resource_kind, 'A log of urges to confess intrusive thoughts to others, tracking who, what relief came and how soon the doubt returned.', 'Use it to show how confessing works as a ritual and shorten the reach of the urge.', array['Adults', 'Teens']::text[], 'Five minutes per urge for two weeks', 'The urge to tell a partner or parent about an intrusive thought often hides in plain sight as honesty, so introduce the log by explaining that you are tracking relief-seeking, not the content. Each entry records the thought in a word or two, the person the client wanted to tell, whether they did, the relief it brought and how long before the doubt was back. Within a week the entries usually show a relief curve that shortens each time. Pair it with a delay the client picks, and prepare the family member for hearing less, since they often experience the confessions as closeness.', '[{"id": "f0", "type": "textarea", "label": "The intrusive thought, in a word or two"}, {"id": "f1", "type": "textarea", "label": "Who I wanted to tell, and why them"}, {"id": "f2", "type": "textarea", "label": "Did I tell them, and how long did I wait first"}, {"id": "f3", "type": "textarea", "label": "How much relief it brought, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "How long before the doubt came back"}, {"id": "f5", "type": "textarea", "label": "What I did instead when I did not confess"}, {"id": "f6", "type": "textarea", "label": "What I am noticing about the pattern"}]'::jsonb, array['OCD', 'urges', 'self-monitoring']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('theory-a-and-theory-b-sheet', 'Theory A and Theory B Sheet', 'cbt'::resource_kind, 'A two-column sheet weighing the client''s danger theory against the alternative that the problem is worry, and what each predicts.', 'Use it to set up the question the client''s next weeks will test.', array['Adults', 'Teens']::text[], '40 minutes', 'Write Theory A in the client''s own words, such as I am a danger to my family and must check, and Theory B as its alternative: the problem is that I am worried I am a danger and the checking keeps the worry alive. Then work through what each theory predicts about the evidence so far, what living by each has cost, and what each would ask the client to do tomorrow. Do not argue for Theory B; the sheet only has to make it a fair question. Watch for the client treating the sheet itself as reassurance by re-reading it; it is a map for the experiments, not a verdict.', '[{"id": "f0", "type": "textarea", "label": "Theory A: what I believe the problem is, in my words"}, {"id": "f1", "type": "textarea", "label": "Theory B: the problem is that I worry about this, and what I do about the worry"}, {"id": "f2", "type": "textarea", "label": "What Theory A says about the evidence I have so far"}, {"id": "f3", "type": "textarea", "label": "What Theory B says about the same evidence"}, {"id": "f4", "type": "textarea", "label": "What living by Theory A has cost me"}, {"id": "f5", "type": "textarea", "label": "What Theory B would have me do tomorrow"}, {"id": "f6", "type": "textarea", "label": "A small thing I could do this week that only makes sense under Theory B"}]'::jsonb, array['OCD', 'core CBT', 'formulation']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('rope-drop-for-doubt-arguments', 'Rope Drop for Doubt Arguments', 'act'::resource_kind, 'A practice for noticing when the client has picked up the rope against a doubt, reviewing and arguing, and dropping it mid-pull.', 'Use it to end the mental tug-of-war with doubt without needing to win it.', array['Adults', 'Teens']::text[], '25 minutes', 'Mental reviewing and arguing with a doubt is the rope, and most clients do not notice they have picked it up until an hour has gone. Map the client''s own signs of pulling, then practice in session with a live doubt: notice the pull, say rope, open the hands and turn attention to the next thing in the room. The doubt stays on the other end; the client stops pulling. Expect the first drops to feel like negligence, and say so beforehand. Keep the practice short and frequent, and review which doubts the client could drop and which still pull them in.', '[{"id": "f0", "type": "textarea", "label": "The doubts my mind most often argues with"}, {"id": "f1", "type": "textarea", "label": "My signs that I have picked up the rope"}, {"id": "f2", "type": "textarea", "label": "What a pull costs me in time and attention"}, {"id": "f3", "type": "textarea", "label": "The word I will use when I notice: rope"}, {"id": "f4", "type": "textarea", "label": "What I will turn toward in the room when I drop it"}, {"id": "f5", "type": "textarea", "label": "What dropping felt like the first few times"}, {"id": "f6", "type": "textarea", "label": "A doubt I dropped this week, and what happened"}]'::jsonb, array['OCD', 'defusion', 'acceptance', 'core ACT']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('cope-ahead-plan-for-a-ritual-free-outing', 'Cope Ahead Plan for a Ritual-Free Outing', 'dbt'::resource_kind, 'A DBT cope ahead plan rehearsed in imagery for one outing the client will do without checking, washing or seeking reassurance.', 'Use it to rehearse an outing without rituals until the plan is familiar before the day.', array['Adults', 'Teens']::text[], '30 minutes', 'Choose one specific outing, such as leaving the house for a movie without going back to check the stove, and walk through it in detail: the moment the urge will hit, the skill the client will use, and what they will do if the urge spikes rather than fades. Rehearse the scene in imagery twice in session, with the client describing the urge rising and the skill working, and once more the night before. The usual slip is a plan that quietly includes a ritual, such as one final look; read it back for those. Afterward review the gap between the predicted and the actual urge.', '[{"id": "f0", "type": "textarea", "label": "The outing I will do without rituals, and when"}, {"id": "f1", "type": "textarea", "label": "The moment I expect the urge to hit"}, {"id": "f2", "type": "textarea", "label": "The skill I will use at that moment"}, {"id": "f3", "type": "textarea", "label": "What I will do if the urge spikes instead of fading"}, {"id": "f4", "type": "textarea", "label": "The scene as I rehearsed it, including the urge passing"}, {"id": "f5", "type": "textarea", "label": "Anything in my plan that is secretly a ritual"}, {"id": "f6", "type": "textarea", "label": "What actually happened compared with the rehearsal"}]'::jsonb, array['OCD', 'cope ahead', 'core DBT']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('panic-at-work-plan-sheet', 'Panic at Work Plan Sheet', 'worksheet'::resource_kind, 'A plan for a panic attack at work: where to go, what to say, how long to stay and how to return to the desk.', 'Use it to make a workplace panic attack survivable without a sick day or a story.', array['Adults']::text[], '25 minutes', 'Most clients plan for panic at home and are blindsided by it in a meeting. Map the workplace: the nearest private spot, a plausible one-line exit, the longest they will allow themselves away before returning, and what they will do in those minutes. Returning is the part that matters, since leaving for the day teaches the body that the office is the danger. Decide in advance whether anyone at work knows and what the client wants them to do, which is usually less than the colleague would offer. Rehearse the exit line aloud and keep the sheet in the phone rather than a drawer.', '[{"id": "f0", "type": "textarea", "label": "Where panic is most likely to hit at work"}, {"id": "f1", "type": "textarea", "label": "The nearest spot where I can be alone for five minutes"}, {"id": "f2", "type": "textarea", "label": "My one-line exit, said aloud"}, {"id": "f3", "type": "textarea", "label": "The longest I will stay away before returning"}, {"id": "f4", "type": "textarea", "label": "What I will do during those minutes"}, {"id": "f5", "type": "textarea", "label": "Who at work knows, and what I want them to do"}, {"id": "f6", "type": "textarea", "label": "How I will return to my desk and the task I left"}, {"id": "f7", "type": "textarea", "label": "What I will tell myself afterward"}]'::jsonb, array['panic attacks', 'planning', 'coping skills']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('looking-panicked-observer-experiment', 'Looking Panicked Observer Experiment', 'cbt'::resource_kind, 'A behavioral experiment testing the belief that everyone can see a panic attack by asking an observer what they actually noticed.', 'Use it to test how visible panic really is from the outside.', array['Adults', 'Teens']::text[], 'One week', 'Write the prediction precisely: what the client believes shows, such as shaking hands or a red face, and how many people in a room would notice. Then run it two ways. In session, have the client bring on sensations through fast breathing or stair climbing while you note what you can actually see and compare with their inner rating. In the week, a trusted person sits with them through a moderate episode and writes what they saw before the client says anything. The gap between felt and seen is usually wide, and the client needs to hear it from a real observer, not from you.', '[{"id": "f0", "type": "textarea", "label": "What I believe other people can see when I panic"}, {"id": "f1", "type": "textarea", "label": "How many people out of ten I think would notice"}, {"id": "f2", "type": "textarea", "label": "What I felt during the in-session practice, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What my therapist said they could see"}, {"id": "f4", "type": "textarea", "label": "What my observer wrote after the episode this week"}, {"id": "f5", "type": "textarea", "label": "What I felt during that episode, 0 to 10"}, {"id": "f6", "type": "textarea", "label": "What the gap between felt and seen tells me"}, {"id": "f7", "type": "textarea", "label": "My updated prediction"}]'::jsonb, array['panic attacks', 'behavioral experiment', 'core CBT']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('the-one-who-notices-panic-practice', 'The One Who Notices Panic Practice', 'act'::resource_kind, 'A self-as-context practice for finding the part of the client that notices the pounding heart, which the panic does not touch.', 'Use it to give the client a place to stand inside a panic attack that is not the panic.', array['Adults', 'Teens']::text[], '20 minutes', 'Run it first in session when calm: the client notices a sensation, then notices that they are noticing it, then asks who is doing the noticing. Keep the language plain and avoid anything mystical, since clients in panic want a foothold rather than a philosophy. Once the move is familiar, practice it with mild sensations brought on in session, then add it to the first minute of a real episode as a single question: who is noticing this. Watch for the practice becoming a way to push panic away, which turns it into another control strategy; the noticer watches the panic, it does not switch it off.', '[{"id": "f0", "type": "textarea", "label": "A sensation I noticed, and the part of me that noticed it"}, {"id": "f1", "type": "textarea", "label": "What is true about the noticer that is not true about the sensation"}, {"id": "f2", "type": "textarea", "label": "The question I will ask in the first minute: who is noticing this"}, {"id": "f3", "type": "textarea", "label": "What happened when I tried it with a mild sensation"}, {"id": "f4", "type": "textarea", "label": "What happened when I tried it during a real wave"}, {"id": "f5", "type": "textarea", "label": "What the noticer can see that the panic cannot"}]'::jsonb, array['panic attacks', 'self-as-context', 'core ACT', 'mindfulness']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('half-smile-and-willing-hands-for-panic', 'Half-Smile and Willing Hands for Panic', 'dbt'::resource_kind, 'A DBT skill card pairing a half-smile and open, willing hands with the first signs of a panic surge.', 'Use it to change the body''s posture toward panic from bracing to allowing.', array['Adults', 'Teens']::text[], '15 minutes', 'Teach the two body moves when the client is calm: a slight softening at the corners of the mouth, and hands turned open on the lap or at the sides, shoulders down. Both are small enough to do in a checkout line without being seen. The point is that a clenched jaw and fists tell the body the alarm is correct, and the open posture sends a different message without requiring the client to believe anything. Practice while bringing on mild sensations in session, then use at the first sign of a surge. Clients often feel foolish; name it as a posture for the body, not an expression for others.', '[{"id": "f0", "type": "textarea", "label": "Where I brace first when panic starts: jaw, fists, shoulders"}, {"id": "f1", "type": "textarea", "label": "What the half-smile feels like in my face, in my words"}, {"id": "f2", "type": "textarea", "label": "What willing hands look like for me in public"}, {"id": "f3", "type": "textarea", "label": "The first sign of a surge where I will use them"}, {"id": "f4", "type": "textarea", "label": "What changed in the wave when I tried it"}, {"id": "f5", "type": "textarea", "label": "What stayed the same"}]'::jsonb, array['panic attacks', 'core DBT', 'willingness', 'acceptance']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('when-panic-cancels-plans-conversation', 'When Panic Cancels Plans Conversation', 'couples'::resource_kind, 'A conversation for a couple whose outings keep ending in a canceled plan, covering what each feels and a fair way to decide next time.', 'Use it to stop canceled plans from becoming a quiet resentment in the relationship.', array['Couples']::text[], '45 minutes', 'The partner who panics usually carries guilt and the other carries disappointment they feel they are not allowed to voice, and both go unsaid. Let each speak in turn without the other fixing it. Then build a rule for next time that is neither always go nor always cancel: a graded option such as the partner going alone, going for a shorter time, or a planned early exit, and who makes the call. Watch for the non-panicking partner volunteering to cancel everything, which protects the relationship tonight and shrinks it over months. Agree on one plan this month that will go ahead in some form.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what happens in me in the hour before we are due to leave"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I feel after we cancel"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I feel when a plan is canceled, including the parts I usually keep to myself"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I need that is not an apology"}, {"id": "f4", "type": "textarea", "label": "Our graded options for next time, from a shorter version to going separately"}, {"id": "f5", "type": "textarea", "label": "Who makes the call, and by when"}, {"id": "f6", "type": "textarea", "label": "One plan this month that will happen in some form"}, {"id": "f7", "type": "textarea", "label": "How we will talk about it the morning after"}]'::jsonb, array['panic attacks', 'couples', 'repair', 'avoidance']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('stop-nagging-behavioral-experiment', 'Stop Nagging Behavioral Experiment', 'cbt'::resource_kind, 'A behavioral experiment testing a parent''s prediction of what happens when the reminders stop for one week.', 'Use it to test the belief that a child only acts when a parent keeps pushing.', array['Adults']::text[], 'One week', 'Pick one task the parent reminds about more than three times a day, usually homework, teeth or getting out the door. Write the exact prediction before the week starts, with a number if possible, and agree on a single calm instruction and a natural consequence in its place. Parents tend to count the misses and not the days it went fine, so have them log every day, not just bad ones. If the child is young or the task is a safety one, choose a different task. Review the prediction against the log and ask what the nagging was really doing for the parent.', '[{"id": "f0", "type": "textarea", "label": "The task I keep reminding about, and how many times a day I remind"}, {"id": "f1", "type": "textarea", "label": "My prediction: if I stop reminding for a week, this is exactly what will happen"}, {"id": "f2", "type": "textarea", "label": "How sure I am, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "The one instruction I will give instead, and what follows if it is not done"}, {"id": "f4", "type": "textarea", "label": "Day by day: what actually happened"}, {"id": "f5", "type": "textarea", "label": "How the prediction compares with the log"}, {"id": "f6", "type": "textarea", "label": "What I now believe about reminding, and what I will try next"}]'::jsonb, array['parenting', 'behavioral experiment', 'core CBT']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('loosening-the-reins-values-sheet', 'Loosening the Reins Values Sheet', 'act'::resource_kind, 'A values worksheet for the parent of a teen who is pulling for independence the parent is not ready to give.', 'Use it to separate what the parent values from what fear is steering.', array['Adults']::text[], '30 minutes', 'Ask what the parent wants their teen to be able to do at 25, then work backward to what the teen would need to practice now. Fear usually shows up as a rule, no sleepovers, phone checked nightly, and the sheet asks whether that rule serves the value or the fear. Watch for the parent who answers with the teen''s flaws instead of their own values; bring it back to what kind of parent they want to be in this stage. End with one small freedom the parent is willing to give while feeling uneasy, and name the unease as the price of the value.', '[{"id": "f0", "type": "textarea", "label": "What I want my teen to be able to do on their own by the time they are 25"}, {"id": "f1", "type": "textarea", "label": "What they would have to practice this year for that to happen"}, {"id": "f2", "type": "textarea", "label": "A rule I hold that is really about my fear"}, {"id": "f3", "type": "textarea", "label": "What my fear says will happen if I loosen it"}, {"id": "f4", "type": "textarea", "label": "The parent I want to be during these years, in three words"}, {"id": "f5", "type": "textarea", "label": "One freedom I am willing to give this month while feeling uneasy"}, {"id": "f6", "type": "textarea", "label": "How I will handle the unease without taking the freedom back"}]'::jsonb, array['parenting', 'values', 'willingness', 'core ACT']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('giving-in-pros-and-cons-grid', 'Giving In Pros and Cons Grid', 'dbt'::resource_kind, 'A four-box DBT pros and cons grid a parent fills in before the next meltdown about giving in versus holding a limit.', 'Use it to help a parent decide in a calm moment how they will act in a hot one.', array['Adults']::text[], '20 minutes', 'Fill the grid in session for one specific limit, like screens off at eight. Pros of giving in are real and parents are often ashamed to write them, so name the quiet house and the ended tantrum yourself. The long-term column is where the work is: ask what the child learns each time the limit moves. Then have the parent pick the boxes they want to read when the urge to give in peaks and copy them onto a card for the fridge. Review after a week which box they read and whether it held.', '[{"id": "f0", "type": "textarea", "label": "The limit I keep caving on"}, {"id": "f1", "type": "textarea", "label": "Pros of giving in, right now"}, {"id": "f2", "type": "textarea", "label": "Cons of giving in, right now and over the months"}, {"id": "f3", "type": "textarea", "label": "Pros of holding the limit"}, {"id": "f4", "type": "textarea", "label": "Cons of holding the limit, including what it costs me"}, {"id": "f5", "type": "textarea", "label": "The lines I will read when the urge to give in peaks"}, {"id": "f6", "type": "textarea", "label": "After a week: which box I read, and whether the limit held"}]'::jsonb, array['parenting', 'pros and cons', 'core DBT', 'urges']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('overruled-in-front-of-the-kids-repair', 'Overruled in Front of the Kids Repair', 'couples'::resource_kind, 'A repair script for the moment one parent contradicts the other''s decision in front of the children.', 'Use it to give a couple a way to fix an undermining moment without a fight.', array['Couples']::text[], '30 minutes', 'Have each partner describe a recent overruling from their seat only: the one who was contradicted and the one who stepped in. The stepping-in partner usually had a reason, often that the first decision felt harsh, and the sheet gives that reason a private channel so it stops leaking out in front of the kids. Agree on a holding phrase for the moment, something like we will talk about it later, and a time within the day to do so. Role-play once in session; the hard part is the overruled partner accepting a later conversation instead of a public win.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a time I was overruled in front of the kids, and what it did to me"}, {"id": "f1", "type": "textarea", "label": "Partner B: a time I stepped in, and what I was worried about"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I need to hear afterward so I can let it go"}, {"id": "f3", "type": "textarea", "label": "Partner B: how I will raise a concern privately next time"}, {"id": "f4", "type": "textarea", "label": "Both: our holding phrase for the moment, said in front of the kids"}, {"id": "f5", "type": "textarea", "label": "Both: when in the day we will talk it through"}, {"id": "f6", "type": "textarea", "label": "Both: what we will tell the kids if a decision changes"}]'::jsonb, array['parenting', 'couples', 'repair', 'communication']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('hand-on-my-arm-waiting-signal-craft', 'Hand on My Arm Waiting Signal Craft', 'kids'::resource_kind, 'A child decorates a wristband and practices the signal for waiting while a parent finishes a call or a sentence.', 'Use it to replace interrupting with a signal both parent and child can keep.', array['Children', 'Adults']::text[], '30 minutes, then daily', 'The child decorates a paper wristband the parent wears at home as a reminder. The rule is simple: the child puts a hand on the parent''s arm, the parent covers it to say I know you are there, and the parent turns to the child within a minute. Practice it in session with you on a pretend call. The parent''s part is the one that fails, they forget to cover the hand or make the child wait too long, so rehearse the parent''s side more than the child''s. Praise the waiting, not the quiet. If a child discloses harm while you work, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw or decorate the wristband and write our signal on it"}, {"id": "f1", "type": "textarea", "label": "What I do when I need my grown-up and they are busy"}, {"id": "f2", "type": "textarea", "label": "What my grown-up does to show they know I am waiting"}, {"id": "f3", "type": "textarea", "label": "Something I can do with my hands while I wait"}, {"id": "f4", "type": "textarea", "label": "Parent: how I will make sure I turn to my child within a minute"}, {"id": "f5", "type": "textarea", "label": "A time this week the signal worked"}]'::jsonb, array['parenting', 'children', 'play', 'routines']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('unsolicited-advice-defusion-sheet', 'Unsolicited Advice Defusion Sheet', 'act'::resource_kind, 'A defusion worksheet for new parents drowning in conflicting advice from family, forums and strangers.', 'Use it to help a new parent hold advice lightly and act from their own values.', array['Adults']::text[], '25 minutes', 'Collect the advice the parent has received in the last week, verbatim, including from their own mind, and notice that much of it contradicts the rest. Practice labeling each as a thought the mind is offering, so the parent can hear advice without obeying or arguing with it. The trap is turning this into a debate about which advice is right; keep it on workability, whether following it moves the parent toward the parent they want to be. Finish with one piece of advice they will thank and set down, and one they will keep because it fits their values.', '[{"id": "f0", "type": "textarea", "label": "Advice I was given this week, word for word, and who gave it"}, {"id": "f1", "type": "textarea", "label": "Advice my own mind keeps giving me"}, {"id": "f2", "type": "textarea", "label": "Where two pieces of advice contradict each other"}, {"id": "f3", "type": "textarea", "label": "Rewrite each piece as: I am having the thought that I should..."}, {"id": "f4", "type": "textarea", "label": "The kind of parent I want to be, in my own words"}, {"id": "f5", "type": "textarea", "label": "Advice I will thank and set down"}, {"id": "f6", "type": "textarea", "label": "Advice I will keep because it fits my values, and how I will use it"}]'::jsonb, array['perinatal and postpartum', 'defusion', 'values', 'core ACT']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('check-the-facts-on-what-the-crying-means', 'Check the Facts on What the Crying Means', 'dbt'::resource_kind, 'A DBT check the facts sheet for the story a new parent tells when the baby will not settle.', 'Use it to separate a baby''s crying from the verdict a parent attaches to it.', array['Adults']::text[], '20 minutes', 'Most new parents have a sentence that plays when the baby cries, usually some version of they do not want me or I am failing. Write it down exactly, then check it: what does the crying prove, what else explains it, does the emotion fit the facts and is it the right size. Expect shame to arrive in the room when the sentence is spoken, and slow down there. If the facts fit, the sheet moves to problem solving, like a feeding or sleep plan with the pediatrician; if they do not, agree on an opposite action for the next cry. Keep it short; this is a sheet for the fourth trimester, not an essay.', '[{"id": "f0", "type": "textarea", "label": "What the baby was doing, in plain description"}, {"id": "f1", "type": "textarea", "label": "The sentence that played in my head"}, {"id": "f2", "type": "textarea", "label": "The emotion and how strong it was, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "What the crying actually proves, and what else could explain it"}, {"id": "f4", "type": "textarea", "label": "Does my emotion fit the facts? Is it the right size?"}, {"id": "f5", "type": "textarea", "label": "If the facts fit: one problem-solving step. If not: what I will do differently at the next cry"}]'::jsonb, array['perinatal and postpartum', 'check the facts', 'core DBT', 'emotion regulation']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('baby-safety-thermostat-conversation', 'Baby Safety Thermostat Conversation', 'couples'::resource_kind, 'A couples conversation for partners whose sense of how careful to be with the baby is set at different levels.', 'Use it to turn a safety standoff into one shared plan for the things that matter.', array['Couples']::text[], '45 minutes', 'One partner checks the breathing hourly and the other says relax, and each thinks the other is the problem. Have each rate their thermostat and name what set it, often a past loss or a story they read. The exercise sorts worries into three piles: what the pediatrician says is safety, what is preference, and what is the anxious partner''s mind asking for reassurance. The relaxed partner''s job is to take pile one seriously without eye-rolling; the anxious partner''s job is to let pile three be met with support rather than a check. Agree on who does what for the top three items.', '[{"id": "f0", "type": "textarea", "label": "Partner A: where my safety thermostat sits, 1 to 10, and what set it there"}, {"id": "f1", "type": "textarea", "label": "Partner B: where mine sits, 1 to 10, and what set it there"}, {"id": "f2", "type": "textarea", "label": "Partner A: the three things I most want us to do the same way"}, {"id": "f3", "type": "textarea", "label": "Partner B: the three things I most want us to do the same way"}, {"id": "f4", "type": "textarea", "label": "Both: which of these are safety, which are preference, which are reassurance"}, {"id": "f5", "type": "textarea", "label": "Both: our shared plan for the top three, and who does what"}, {"id": "f6", "type": "textarea", "label": "Both: what the worried partner will say instead of checking, and how the other will answer"}]'::jsonb, array['perinatal and postpartum', 'couples', 'safety', 'communication']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('feeding-time-busy-box-craft', 'Feeding Time Busy Box Craft', 'kids'::resource_kind, 'An older sibling decorates and fills a box of things to do alone while a parent feeds the new baby.', 'Use it to give a displaced older child a plan for the moments that sting most.', array['Children', 'Adults']::text[], '30 minutes, then daily', 'Feeding is when the older child most often acts up, because the parent is pinned in a chair. The child decorates a shoebox and picks five quiet things for it; the box only comes out at feeding time so it stays special. The parent''s part is to sit the child nearby, narrate what they see them doing, and offer a story or a song during the feed so the child is included rather than sent away. Rotate the contents weekly. For the child who insists on helping with the baby every time, add one real helper job to the box. If a child discloses harm while you work, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Decorate the box and give it a name"}, {"id": "f1", "type": "textarea", "label": "Five things that go in my box"}, {"id": "f2", "type": "textarea", "label": "Where I sit when the baby is eating"}, {"id": "f3", "type": "textarea", "label": "What my grown-up and I can do together while the baby eats"}, {"id": "f4", "type": "textarea", "label": "My one real helper job"}, {"id": "f5", "type": "textarea", "label": "Parent: what I will say to my older child when the baby needs me"}]'::jsonb, array['perinatal and postpartum', 'children', 'family', 'play']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('me-too-card-draw-for-new-parents', 'Me Too Card Draw for New Parents', 'game'::resource_kind, 'A group game where new parents draw cards of thoughts other parents have had and say me too, pass, or not me.', 'Use it to break the silence around the thoughts new parents are ashamed of.', array['Groups', 'Adults']::text[], '45 minutes', 'Prepare thirty cards with thoughts such as I felt nothing when I first held them, I miss my old life, I wished I could hand the baby back. Rules: sit in a circle; each turn one player draws and reads a card aloud, then everyone answers me too, pass, or not me on a count of three. No one explains unless they want to; the reader picks the next. Include a few cards on hopelessness and not wanting to be here, read those yourself, and run the game in session, never as homework, so you can follow up individually. Debrief on what hearing me too was like, and send everyone off with the 988 line.', '[{"id": "f0", "type": "textarea", "label": "A card I said me too to, and what it was like to hear others say it"}, {"id": "f1", "type": "textarea", "label": "A card I passed on"}, {"id": "f2", "type": "textarea", "label": "A thought I have had that was not on a card"}, {"id": "f3", "type": "textarea", "label": "If I ever feel hopeless or think about not being here, I will call or text 988 or reach my clinician"}, {"id": "f4", "type": "textarea", "label": "One person in the group I would be willing to text this week"}, {"id": "f5", "type": "textarea", "label": "What I want to say in the debrief"}]'::jsonb, array['perinatal and postpartum', 'group', 'play', 'support']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('ask-for-what-you-deserve-dear-man', 'Ask for What You Deserve DEAR MAN', 'dbt'::resource_kind, 'A DEAR MAN script for the ask a client with low self-worth keeps not making, like a raise or a fair share of the work.', 'Use it to let a client practice asking as if their needs count.', array['Adults', 'Teens']::text[], '30 minutes', 'Start by listing the asks the client has swallowed in the last month; the list itself is data about how they rate their own needs. Pick one with a real chance of a yes and build the DEAR MAN line by line, keeping Describe free of apology and Assert in the form I want, not would it be okay if. Clients with low self-worth tend to flood the Express step with justification; cut it to one sentence. Role-play with you as a mildly unhelpful other and rehearse the Negotiate step, since a partial yes is the usual outcome. Debrief on what asking did to their sense of worth, whatever the answer.', '[{"id": "f0", "type": "textarea", "label": "Asks I have swallowed this month"}, {"id": "f1", "type": "textarea", "label": "The one I will make, and who I will make it to"}, {"id": "f2", "type": "textarea", "label": "Describe: the facts, no apology"}, {"id": "f3", "type": "textarea", "label": "Express: one sentence about how it affects me"}, {"id": "f4", "type": "textarea", "label": "Assert: I want..."}, {"id": "f5", "type": "textarea", "label": "Reinforce: what they get from saying yes"}, {"id": "f6", "type": "textarea", "label": "Stay Mindful, Appear confident, Negotiate: what I will do if they push back"}, {"id": "f7", "type": "textarea", "label": "After asking: what it did to my sense of worth, whatever the answer"}]'::jsonb, array['self-esteem', 'DEAR MAN', 'interpersonal effectiveness', 'core DBT']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('reassurance-loop-exit-plan', 'Reassurance Loop Exit Plan', 'couples'::resource_kind, 'A couples plan for the loop where one partner keeps asking if they are good enough and the other keeps answering.', 'Use it to replace a reassurance habit with support that actually lands.', array['Couples']::text[], '40 minutes', 'Map the loop together: the question, the answer, the relief, and how long the relief lasts, usually minutes. The asking partner names what they are really hoping to hear and notices the answer never quite does it; the answering partner names the fatigue they have not said out loud. Agree on a replacement: the asker says the fear out loud as a fear, and the partner responds with one warm line and physical closeness rather than a case for the asker''s worth. Expect the loop to get louder in the first week before it quiets. Watch for the answering partner turning this into a reason to withdraw.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the question I keep asking, and how long the answer helps"}, {"id": "f1", "type": "textarea", "label": "Partner B: what answering again and again has been like for me"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I am really hoping to hear, and why it never quite lands"}, {"id": "f3", "type": "textarea", "label": "Partner B: the one warm line I will say instead of making the case"}, {"id": "f4", "type": "textarea", "label": "Partner A: how I will say the fear as a fear instead of asking the question"}, {"id": "f5", "type": "textarea", "label": "Both: what we will do when the old loop starts anyway"}, {"id": "f6", "type": "textarea", "label": "Both: after a week, what changed"}]'::jsonb, array['self-esteem', 'couples', 'reassurance', 'support']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('teach-a-grown-up-lesson-plan-craft', 'Teach a Grown-Up Lesson Plan Craft', 'kids'::resource_kind, 'A child plans and delivers a short lesson on something they know, with the parent as the student.', 'Use it to let a child feel capable from the inside, not from praise.', array['Children', 'Adults']::text[], '30 minutes, then one lesson at home', 'The child picks something they know and the parent does not, a game, a drawing trick, a dinosaur fact, and draws a three-step lesson plan with pictures. The parent''s part is to be a real student: ask questions, try it, get it slightly wrong and let the child correct them. Children with low confidence pick something they think is too small; small and real beats big and vague. Debrief on what it felt like to be the one who knew. Skip the praise afterward; ask what the parent learned instead. If a child discloses harm while you work, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Something I know how to do that my grown-up does not"}, {"id": "f1", "type": "textarea", "label": "Draw my lesson in three steps"}, {"id": "f2", "type": "textarea", "label": "A question my student might ask"}, {"id": "f3", "type": "textarea", "label": "How the lesson went"}, {"id": "f4", "type": "textarea", "label": "Something my grown-up got wrong and I fixed"}, {"id": "f5", "type": "textarea", "label": "Parent: what I learned from my child"}]'::jsonb, array['self-esteem', 'children', 'strengths', 'play']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('critic-versus-coach-improv-game', 'Critic Versus Coach Improv Game', 'game'::resource_kind, 'A group improv game where one player voices a situation''s inner critic and another answers as a fair coach.', 'Use it to give a group practice hearing and answering a harsh inner voice out loud.', array['Groups', 'Teens', 'Adults']::text[], '45 minutes', 'Rules: a volunteer describes a small real situation, like sending a text with a typo. The player on their left plays the critic for thirty seconds, the player on their right plays a coach who is fair, specific and not sugary. The volunteer then says which lines they would keep. Then the turn passes left so everyone plays all three parts. The critic role is the fun one and groups get loud, so cap it at thirty seconds and stop any critic that drifts from the situation to the person. Debrief on how familiar the critic sounded, which coach lines were believable, and what made the sugary ones fail.', '[{"id": "f0", "type": "textarea", "label": "The situation I brought"}, {"id": "f1", "type": "textarea", "label": "A critic line that sounded exactly like my own head"}, {"id": "f2", "type": "textarea", "label": "A coach line I would actually keep"}, {"id": "f3", "type": "textarea", "label": "What made a coach line believable, and what made one fall flat"}, {"id": "f4", "type": "textarea", "label": "What it was like to play the critic for someone else"}, {"id": "f5", "type": "textarea", "label": "A coach line I will try on myself this week"}]'::jsonb, array['self-esteem', 'group', 'play', 'self-criticism']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('over-apologizing-log', 'Over-Apologizing Log', 'worksheet'::resource_kind, 'A week-long log of every sorry a client says, sorted into the ones that were owed and the ones that were reflex.', 'Use it to show a client how often they apologize for existing and to try a replacement.', array['Adults', 'Teens']::text[], 'One week', 'Have the client tally every sorry for a week, with a word on what it was for. Most are for taking up space: asking a question, being passed in a corridor, needing a minute. Sort them into owed, reflex and asking permission, and look at the ratio together. Then pick a replacement that fits, usually thank you for waiting or excuse me, and run week two with the swap. The sorting conversation often surfaces the belief underneath, that their needs are an imposition; note it for later work rather than arguing with it now.', '[{"id": "f0", "type": "textarea", "label": "Every sorry this week, with a word on what it was for"}, {"id": "f1", "type": "textarea", "label": "Which ones were owed, which were reflex, which were asking permission"}, {"id": "f2", "type": "textarea", "label": "What I notice about the ratio"}, {"id": "f3", "type": "textarea", "label": "What my sorries seem to assume about me"}, {"id": "f4", "type": "textarea", "label": "The replacement I will try next week"}, {"id": "f5", "type": "textarea", "label": "Week two: how the swap went and what I felt saying it"}]'::jsonb, array['self-esteem', 'self-monitoring', 'assertiveness', 'habits']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('hosting-at-home-role-split', 'Hosting at Home Role Split', 'couples'::resource_kind, 'A couples plan for having guests over that gives the socially anxious partner real roles instead of hiding in the kitchen.', 'Use it to make hosting a shared job and a graded step rather than an ordeal.', array['Couples']::text[], '30 minutes', 'Hosting is often the social situation a couple avoids longest, and the anxious partner usually ends up washing dishes all night. Plan one small gathering: the anxious partner chooses two roles that put them in the room, like greeting at the door or running the music, and one escape job they can use once, not all evening. The other partner names what they will do when they see their partner retreating, which is to draw them into a conversation, not to announce it. Agree on the signal for a five-minute break and the review question for afterward. Scale up the guest count over several events.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I usually do when we have people over, and what I would rather do"}, {"id": "f1", "type": "textarea", "label": "Partner A: my two in-the-room roles for this gathering"}, {"id": "f2", "type": "textarea", "label": "Partner A: my one escape job, and the limit on it"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I will do when I see my partner retreating"}, {"id": "f4", "type": "textarea", "label": "Partner B: what I will not say in front of guests"}, {"id": "f5", "type": "textarea", "label": "Both: our break signal and the guest count for this time"}, {"id": "f6", "type": "textarea", "label": "Both: afterward, what went better than predicted"}]'::jsonb, array['social anxiety', 'couples', 'exposure', 'support']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('join-the-game-recess-map', 'Join the Game Recess Map', 'kids'::resource_kind, 'A child draws the playground and the steps for joining a game already in progress, then practices with a parent.', 'Use it to give a shy child a concrete way into play instead of watching from the edge.', array['Children', 'Adults']::text[], '30 minutes, then practice at home', 'The child draws their playground with where the games happen and where they usually stand. Together, mark a route: watch for a minute, stand close, say one line like can I play or whose team needs one, and if the answer is no, try the next game. The parent''s part is to rehearse the line at home as a game, playing both a yes and a kind no so the child has done the no before it happens. Keep the line short; shy children add too many words. Review after a week which spot on the map they tried. If a child discloses harm while you work, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw my playground, with the games and where I usually stand"}, {"id": "f1", "type": "textarea", "label": "The game I want to join"}, {"id": "f2", "type": "textarea", "label": "My joining line"}, {"id": "f3", "type": "textarea", "label": "What I will do if they say no"}, {"id": "f4", "type": "textarea", "label": "Parent: how we practiced the line at home, including a kind no"}, {"id": "f5", "type": "textarea", "label": "What happened when I tried it"}]'::jsonb, array['social anxiety', 'children', 'social skills', 'play']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('follow-up-question-ping-pong', 'Follow-Up Question Ping Pong', 'game'::resource_kind, 'A pairs game where players keep a conversation going using only follow-up questions, scoring rallies.', 'Use it to teach that curiosity, not cleverness, keeps a conversation alive.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Rules: pairs sit facing each other. One player makes a plain statement about their week. The other must respond with a follow-up question that uses something in the statement; the first answers, and the question goes back. A rally ends when someone changes the subject, asks a closed question, or goes silent for five seconds. Count the rally, then swap partners and take turns starting; play three rounds. Clients who fear they have nothing to say find they only need to listen for the next hook. Debrief on which questions opened things up and whether anxiety faded once a rally got going.', '[{"id": "f0", "type": "textarea", "label": "My longest rally and who it was with"}, {"id": "f1", "type": "textarea", "label": "A follow-up question that opened something up"}, {"id": "f2", "type": "textarea", "label": "What ended my rallies most often"}, {"id": "f3", "type": "textarea", "label": "What I noticed about my anxiety once a rally got going"}, {"id": "f4", "type": "textarea", "label": "A person I will try one follow-up question with this week"}]'::jsonb, array['social anxiety', 'group', 'play', 'social skills']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('silence-tolerance-log', 'Silence Tolerance Log', 'worksheet'::resource_kind, 'A log of pauses in conversation, how long they really lasted, and what the client did to fill them.', 'Use it to loosen the rule that every silence is the client''s fault to fix.', array['Adults', 'Teens']::text[], 'One week', 'Clients with social anxiety take a two-second pause as an emergency and rush to fill it, often with the apology or the joke they later replay. Have them log pauses for a week, estimating length before and after, and noting who ended the pause and how. Most find the other person ends half of them and that nothing bad followed. In week two, set a target: let three pauses a day run until the other person fills them. Pair it with dropping the filler safety behavior. Review the log for any pause that actually went badly and what was different about it.', '[{"id": "f0", "type": "textarea", "label": "The pause: where, with whom, and how long it felt"}, {"id": "f1", "type": "textarea", "label": "How long it probably lasted"}, {"id": "f2", "type": "textarea", "label": "What I did to fill it, if I did"}, {"id": "f3", "type": "textarea", "label": "Who ended it, and what happened next"}, {"id": "f4", "type": "textarea", "label": "Week two: pauses I let run, and what the other person did"}, {"id": "f5", "type": "textarea", "label": "A rule about silence I am starting to doubt"}]'::jsonb, array['social anxiety', 'self-monitoring', 'safety behaviors', 'exposure']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('felt-image-versus-seen-image-sheet', 'Felt Image Versus Seen Image Sheet', 'cbt'::resource_kind, 'A CBT sheet comparing the picture a client has of how they look when anxious with what an observer actually sees.', 'Use it to loosen the felt image that drives self-focus in social situations.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask the client to describe, as a picture, how they believe they looked in a recent anxious moment: the red face, the shaking hands, the stupid expression. Then build the observer''s image from outside evidence: what a friend said, a mirror check done calmly, a recording, or your own observation in session. Clients find the felt image comes from how the anxiety feels inside, not from anything seen, and that the two do not match. Finish with a phrase for the moment that points attention outward. Do not argue the felt image away; let the evidence do it over several uses.', '[{"id": "f0", "type": "textarea", "label": "The situation and the moment I felt most seen"}, {"id": "f1", "type": "textarea", "label": "How I believe I looked, as a detailed picture"}, {"id": "f2", "type": "textarea", "label": "Where this picture comes from: what I saw, or how I felt inside"}, {"id": "f3", "type": "textarea", "label": "What an observer actually saw, from any evidence I have"}, {"id": "f4", "type": "textarea", "label": "The differences between the two pictures"}, {"id": "f5", "type": "textarea", "label": "What I will say to myself next time to turn attention outward"}]'::jsonb, array['social anxiety', 'core CBT', 'evidence', 'attention']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('still-here-people-map', 'Still Here People Map', 'kids'::resource_kind, 'A child draws the people and pets who are still here to look after them after someone has died.', 'Use it to steady a child''s fear that everyone else will leave too.', array['Children', 'Adults']::text[], '30 minutes', 'After a death, many children quietly fear the next person will go. The child draws themselves in the middle and the people and pets still here around them, with what each one does for them. The parent''s part is to sit beside, add names the child forgets, and answer the question that usually comes, will you die too, honestly and simply: everyone dies one day, I plan to be here a very long time, and here is who looks after you if I ever cannot. Rehearse that answer with the parent first. Hang the map by the child''s bed. If a child discloses harm while you work, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw me in the middle and everyone still here around me"}, {"id": "f1", "type": "textarea", "label": "What each person or pet does for me"}, {"id": "f2", "type": "textarea", "label": "Someone my grown-up reminded me of"}, {"id": "f3", "type": "textarea", "label": "A question I want to ask my grown-up"}, {"id": "f4", "type": "textarea", "label": "Parent: how I answered the hardest question"}, {"id": "f5", "type": "textarea", "label": "Where my map will hang"}]'::jsonb, array['grief and loss', 'children', 'support', 'art']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('unhelpful-condolence-rewrite-game', 'Unhelpful Condolence Rewrite Game', 'game'::resource_kind, 'A group game where players draw the clumsy things people say to the grieving and rewrite them into something that helps.', 'Use it to let a grief group laugh at the lines that sting and name what they wish people had said.', array['Groups', 'Adults', 'Teens']::text[], '45 minutes', 'Prepare cards with lines such as everything happens for a reason and you are so strong. Rules: on each turn a player draws, reads the line in the voice it was said in, and the group votes with a thumb on how much it stung. The player has thirty seconds to rewrite it into something that would have helped; the group may offer one edit each. Add blank cards for lines members have heard. Keep it light; the laughter is the point, and it tips into tears once or twice, so leave room. Debrief on what the helpful rewrites had in common and what each member can tell their own people they need.', '[{"id": "f0", "type": "textarea", "label": "A card that stung the most, and why"}, {"id": "f1", "type": "textarea", "label": "A line someone actually said to me"}, {"id": "f2", "type": "textarea", "label": "My rewrite of it"}, {"id": "f3", "type": "textarea", "label": "What the helpful rewrites had in common"}, {"id": "f4", "type": "textarea", "label": "What I will tell one person in my life that I need from them"}]'::jsonb, array['grief and loss', 'group', 'play', 'support']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('their-belongings-decision-planner', 'Their Belongings Decision Planner', 'worksheet'::resource_kind, 'A planner for deciding what to do with a loved one''s belongings in stages, without a deadline from anyone else.', 'Use it to break an overwhelming task into keeps, gives, waits and asks.', array['Adults']::text[], '45 minutes, then over several weeks', 'The closet is often the thing a client cannot face months in, or the thing a relative cleared in a weekend. Sort belongings on paper first into keep, give to someone named, let go, and not yet, and make not yet a legitimate pile with a review date rather than a failure. Ask who is pressuring the timeline and what the client wants to say to them. Plan the first physical session at one drawer, with a person present and a stopping time, since clients tend to start at the hardest item. Watch for the keep pile containing everything; that is fine for now and worth noticing out loud.', '[{"id": "f0", "type": "textarea", "label": "The belongings I am most dreading dealing with"}, {"id": "f1", "type": "textarea", "label": "Who is pressuring me about the timeline, and what I want to say to them"}, {"id": "f2", "type": "textarea", "label": "Keep: things I want near me"}, {"id": "f3", "type": "textarea", "label": "Give: things that belong with a particular person"}, {"id": "f4", "type": "textarea", "label": "Let go: things I can release, and how"}, {"id": "f5", "type": "textarea", "label": "Not yet: things I will look at again on this date"}, {"id": "f6", "type": "textarea", "label": "My first session: which drawer, who is with me, when I stop"}]'::jsonb, array['grief and loss', 'planning', 'pacing', 'decisions']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('feeling-better-is-betrayal-thought-record', 'Feeling Better Is Betrayal Thought Record', 'cbt'::resource_kind, 'A thought record for the moment a grieving client laughs or enjoys something and the guilt lands.', 'Use it to examine the belief that moving through grief means leaving the person behind.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask for the last time the client caught themselves enjoying something, and what their mind said next: if I am happy I have forgotten them, grief is how I stay loyal. Run it as a standard record with the usual evidence columns, and add one question of your own: what would they have wanted for you today. Clients often answer that one quickly and then argue with their own answer, which is the work. The balanced thought tends to land somewhere near I can carry them and still have a good afternoon. Set a small enjoyment for the week as the behavioral test.', '[{"id": "f0", "type": "textarea", "label": "The moment I noticed I was enjoying something"}, {"id": "f1", "type": "textarea", "label": "The thought that came next"}, {"id": "f2", "type": "textarea", "label": "How much I believed it, and what I felt"}, {"id": "f3", "type": "textarea", "label": "Evidence that enjoying things means I have left them behind"}, {"id": "f4", "type": "textarea", "label": "Evidence that it does not"}, {"id": "f5", "type": "textarea", "label": "What they would have wanted for me that afternoon"}, {"id": "f6", "type": "textarea", "label": "A balanced thought, and one enjoyment I will allow this week"}]'::jsonb, array['grief and loss', 'thought record', 'guilt', 'core CBT']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('avoided-places-willingness-walk', 'Avoided Places Willingness Walk', 'act'::resource_kind, 'An ACT committed action plan for returning to the places a client has avoided since the loss.', 'Use it to reclaim the restaurant, the route or the room that grief closed off.', array['Adults', 'Teens']::text[], '40 minutes, then one visit a week', 'List the places the client has steered around since the death: the diner, the park, their room, the grocery aisle. Ask what each place held and what avoiding it is costing, since these are usually the places the relationship lived. Choose the mildest and plan a visit with willingness: how long they will stay, who comes, and what they will make room for, naming the wave before it arrives. The aim is not to feel fine there but to be there with the grief and the memory both. Debrief each visit on what showed up and what they got back. Leave the hardest place until the client asks for it.', '[{"id": "f0", "type": "textarea", "label": "Places I have avoided since the loss"}, {"id": "f1", "type": "textarea", "label": "What each place held, and what avoiding it costs me"}, {"id": "f2", "type": "textarea", "label": "The place I will go first, with whom, and for how long"}, {"id": "f3", "type": "textarea", "label": "What I expect to show up there, and what I will make room for"}, {"id": "f4", "type": "textarea", "label": "What I got back by going"}, {"id": "f5", "type": "textarea", "label": "The next place, when I am ready"}]'::jsonb, array['grief and loss', 'willingness', 'committed action', 'core ACT']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('accepting-influence-card-game', 'Accepting Influence Card Game', 'game'::resource_kind, 'A card game where one player proposes a plan and the other must take one piece of it on board before raising any objection.', 'Use it to practice accepting a partner''s influence before arguing a point.', array['Couples', 'Groups']::text[], '30 minutes', 'Write ten everyday proposals on cards (where to spend a Saturday, how to handle a late bill, which relative to visit). Partner A draws and proposes. Partner B must name one specific part they will accept and say why before saying anything else; only then may they add a concern. Swap after each card. A partner who answers with a but before the yes loses the turn. Score a point for every accept the proposer feels was genuine. Debrief on which cards made accepting hardest and what it felt like to be received first. In a group, pairs rotate so the game is about the skill, not the couple.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the proposal I drew and how I put it"}, {"id": "f1", "type": "textarea", "label": "Partner B: the part I accepted and why"}, {"id": "f2", "type": "textarea", "label": "Partner B: the concern I added afterward"}, {"id": "f3", "type": "textarea", "label": "The card where accepting was hardest and what got in the way"}, {"id": "f4", "type": "textarea", "label": "What it was like to hear my partner take my idea on board"}, {"id": "f5", "type": "textarea", "label": "One place this week I will look for something to accept first"}]'::jsonb, array['relationship issues', 'Gottman', 'play', 'couples']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('resentment-ledger-clearing-sheet', 'Resentment Ledger Clearing Sheet', 'worksheet'::resource_kind, 'A ledger of the old grievances a client keeps on account against a partner, with a column for what each one is really owed.', 'Help a client see which resentments need a conversation, which need a request and which they are ready to close.', array['Adults']::text[], '40 minutes', 'Most clients carry a running tally they never say out loud and then spend it all at once in a fight. Have them list each entry plainly, date it roughly, and write what they wanted at the time. Then sort: entries that still need to be heard, entries that are really a standing request, and entries they are willing to write off now that they have seen them on paper. Watch for a client who writes off everything to seem gracious; the ledger only clears when the live ones get an airing. Pick one entry to raise with the partner and plan the wording.', '[{"id": "f0", "type": "textarea", "label": "The grievances I still keep on account, each in one line"}, {"id": "f1", "type": "textarea", "label": "Roughly when each one started"}, {"id": "f2", "type": "textarea", "label": "What I wanted from my partner at the time"}, {"id": "f3", "type": "textarea", "label": "Entries that still need to be heard"}, {"id": "f4", "type": "textarea", "label": "Entries that are really a request I have never made"}, {"id": "f5", "type": "textarea", "label": "Entries I am willing to close now"}, {"id": "f6", "type": "textarea", "label": "The one I will raise first and how I will put it"}]'::jsonb, array['relationship issues', 'conflict', 'repair', 'communication']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('raising-a-concern-behavioral-experiment', 'Raising a Concern Behavioral Experiment', 'cbt'::resource_kind, 'A behavioral experiment that tests a client''s prediction of how a partner will react when a concern is raised gently and early.', 'Use it to test the belief that speaking up will only make things worse.', array['Adults']::text[], 'Two sessions', 'Clients who swallow concerns usually hold a confident prediction: he will shut down, she will explode, it will cost me the weekend. Pin the prediction down with a percentage of confidence and the exact behavior they expect. Then design a small, low-stakes concern to raise within the week, with a soft opening the client rehearses in session. Afterward compare what happened with what was predicted. The common wobble is choosing a concern too big for a first test; keep it small. If the partner''s reaction was in fact harsh, that is real data, and the next step is a different conversation with you.', '[{"id": "f0", "type": "textarea", "label": "The concern I usually swallow"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen if I raise it, and how sure I am"}, {"id": "f2", "type": "textarea", "label": "The small concern I will raise this week and the words I will open with"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "How my prediction held up"}, {"id": "f5", "type": "textarea", "label": "What I will try next time"}]'::jsonb, array['relationship issues', 'behavioral experiment', 'core CBT', 'communication']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('toward-and-away-moves-in-conflict-sheet', 'Toward and Away Moves in Conflict Sheet', 'act'::resource_kind, 'A sheet for sorting what a client does mid-argument into moves toward the partner they want to be and moves away from it.', 'Use it to help a client pick a toward move for the next argument instead of a reflexive away move.', array['Adults']::text[], '25 minutes', 'Take a recent argument and list every move the client made, including the silences, the eye roll and the closing line. Sort each into toward (in line with how they want to treat this person) or away (driven by the hook of the moment). Away moves are not wrong, they are just costly, and naming them without blame is the work. Then ask what the hook was each time: a thought, a feeling, an old story. Finish by choosing one toward move small enough to do while still angry. Review next session whether the move happened and what the mind said about it.', '[{"id": "f0", "type": "textarea", "label": "The argument, in a sentence"}, {"id": "f1", "type": "textarea", "label": "The moves I made, in order"}, {"id": "f2", "type": "textarea", "label": "Which were toward moves and which were away moves"}, {"id": "f3", "type": "textarea", "label": "What hooked me before each away move"}, {"id": "f4", "type": "textarea", "label": "The person I want to be in a fight, in a few words"}, {"id": "f5", "type": "textarea", "label": "One toward move I can make next time even while angry"}]'::jsonb, array['relationship issues', 'core ACT', 'values', 'conflict']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('interpersonal-effectiveness-myths-challenge', 'Interpersonal Effectiveness Myths Challenge', 'dbt'::resource_kind, 'A DBT sheet for catching the myths that stop a client from asking or saying no in a relationship and writing the challenge to each.', 'Use it to loosen the beliefs that block a client from using DEAR MAN with a partner.', array['Adults', 'Teens']::text[], '30 minutes', 'Before teaching a script, find out why the client has not asked already. Offer the usual myths (if I ask, I am needy; saying no means I do not love them; a good partner would just know) and have them rate how true each feels from 0 to 100. Then write a challenge to each in their own words, not yours. Clients often agree a myth is false in the abstract and still live by it, so pair every challenge with one request they will make this week while the myth is still loud. Bring the rating back next session to see whether action moved it.', '[{"id": "f0", "type": "textarea", "label": "The myths about asking or saying no that I half believe"}, {"id": "f1", "type": "textarea", "label": "How true each one feels right now, from 0 to 100"}, {"id": "f2", "type": "textarea", "label": "Where each myth came from"}, {"id": "f3", "type": "textarea", "label": "My challenge to each myth, in my own words"}, {"id": "f4", "type": "textarea", "label": "The request I will make this week even while the myth is loud"}, {"id": "f5", "type": "textarea", "label": "How true the myth felt after I made the request"}]'::jsonb, array['relationship issues', 'interpersonal effectiveness', 'core DBT', 'DEAR MAN']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('medical-appointment-comfort-plan', 'Medical Appointment Comfort Plan', 'worksheet'::resource_kind, 'A plan a survivor builds for an upcoming medical or dental appointment: what to tell the provider, who comes along, how to pace it.', 'Use it to make routine health care manageable without anyone needing to know the client''s history.', array['Adults', 'Teens']::text[], '30 minutes', 'Appointments that involve touch, being undressed or lying back are a common reason survivors skip care, and the plan works best when it is practical. The client decides how much to say, often just that they need things explained first and to be told before each step. Rehearse the one line they will use and a stop word. Plan who waits outside or sits in, what grounding they will use in the chair, and what they will do for themselves afterward. Keep the focus on the appointment ahead, never on history. If the client wants, write the line on a card they can hand over instead of saying it.', '[{"id": "f0", "type": "textarea", "label": "The appointment and what part of it I expect to be hard"}, {"id": "f1", "type": "textarea", "label": "What I will tell the provider, in one or two lines"}, {"id": "f2", "type": "textarea", "label": "The word or signal I will use if I need a pause"}, {"id": "f3", "type": "textarea", "label": "Who I will bring and what I want them to do"}, {"id": "f4", "type": "textarea", "label": "What I will do with my hands, breath and eyes during the hard part"}, {"id": "f5", "type": "textarea", "label": "How I will look after myself afterward"}, {"id": "f6", "type": "textarea", "label": "Something I can say to myself if it goes less smoothly than planned"}]'::jsonb, array['sexual abuse', 'safety', 'pacing', 'planning']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('healing-pace-thought-record', 'Healing Pace Thought Record', 'cbt'::resource_kind, 'A thought record for the self-critical thoughts a survivor has about how far along they should be by now.', 'Use it to examine thoughts like I should be over this, without going anywhere near what happened.', array['Adults', 'Teens']::text[], '30 minutes', 'The target is the thought about recovery, not the memory, so keep the record on the present: a hard week, a bad night, a reaction that surprised them. Capture the thought (I should be past this, everyone else would be fine by now, I am going backward) and the feeling it brings. Then gather evidence for and against, including what progress has actually looked like and what pace anyone could reasonably expect. The balanced thought should be one they can say out loud. If the record drifts into details of the abuse, bring it back to the thought and end with grounding. Do the first one in session.', '[{"id": "f0", "type": "textarea", "label": "The moment this week when I judged my own progress"}, {"id": "f1", "type": "textarea", "label": "The thought about how far along I should be"}, {"id": "f2", "type": "textarea", "label": "The feeling that came with it, and how strong"}, {"id": "f3", "type": "textarea", "label": "Evidence the thought is accurate"}, {"id": "f4", "type": "textarea", "label": "Evidence it is not the whole picture, including progress I tend to discount"}, {"id": "f5", "type": "textarea", "label": "A fairer thought about my pace that I can say out loud"}, {"id": "f6", "type": "textarea", "label": "How I feel now"}]'::jsonb, array['sexual abuse', 'thought record', 'core CBT', 'self-criticism']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('willing-to-receive-support-practice', 'Willing to Receive Support Practice', 'act'::resource_kind, 'An ACT practice for noticing the mind''s objections to accepting help from safe people and making a small willing move anyway.', 'Use it to help a survivor let support in from the people already offering it.', array['Adults', 'Teens']::text[], '25 minutes', 'Many survivors have a safe person or two and still cannot take what is offered: a ride, a text, a hand on the shoulder. Have the client name the offers they turn down and the thoughts that arrive with each (they will think I am weak, I will owe them, it will not help). Treat those thoughts as passengers, not instructions. Then choose one offer small enough to accept this week with the thoughts still present, and decide what willing looks like in the body. Review how the support landed, not whether the thoughts went away. Keep the exercise in the present tense and on present relationships.', '[{"id": "f0", "type": "textarea", "label": "Support that safe people offer me and I usually decline"}, {"id": "f1", "type": "textarea", "label": "The thoughts that show up when someone offers"}, {"id": "f2", "type": "textarea", "label": "What declining costs me over a month"}, {"id": "f3", "type": "textarea", "label": "The one offer I am willing to accept this week"}, {"id": "f4", "type": "textarea", "label": "What willing will look like in my body and my words when I accept"}, {"id": "f5", "type": "textarea", "label": "How it actually landed"}]'::jsonb, array['sexual abuse', 'willingness', 'support', 'core ACT']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('willing-hands-after-a-startle-card', 'Willing Hands After a Startle Card', 'dbt'::resource_kind, 'A DBT card for using willing hands and a half-smile to settle the body after being startled or touched without warning.', 'Use it to give a survivor a thirty-second skill for the moments after a jump.', array['Adults', 'Teens']::text[], '15 minutes', 'Being startled is ordinary and survivors often follow it with a second wave of shame about reacting. The card separates the two. Teach willing hands (palms open, fingers unclenched, shoulders dropped) and a half-smile, then practice both in session after a mild, agreed cue such as a knock. The client writes the physical steps in their own order and one factual sentence for afterward (that was a startle, it is over). Pair it with naming three things in the room if they need more. Keep it brief and bodily; this is not the place to explore what the startle connected to.', '[{"id": "f0", "type": "textarea", "label": "What a startle feels like in my body in the first seconds"}, {"id": "f1", "type": "textarea", "label": "The steps of willing hands, in the order that works for me"}, {"id": "f2", "type": "textarea", "label": "What my face does for a half-smile"}, {"id": "f3", "type": "textarea", "label": "The factual sentence I will say to myself afterward"}, {"id": "f4", "type": "textarea", "label": "Three things in the room I can name if I need more"}, {"id": "f5", "type": "textarea", "label": "Where I will keep this card"}]'::jsonb, array['sexual abuse', 'core DBT', 'grounding', 'self-soothing']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('where-the-partners-feelings-go-sheet', 'Where the Partner''s Feelings Go Sheet', 'couples'::resource_kind, 'A sheet that gives a survivor''s partner a place for their own anger and helplessness so the survivor is not left managing both.', 'Use it to keep the partner''s reactions from landing on the survivor.', array['Couples']::text[], '40 minutes', 'Partners of survivors often feel rage at the person responsible, helplessness, or guilt about their own needs, and without a plan those feelings get expressed at the survivor or hidden in a way the survivor can read anyway. Partner B names each feeling and chooses where it goes: a friend, their own counseling, a journal, a walk. Partner A says what they can hear and what they cannot. Agree on the signal Partner B uses when they are flooded so they can step away without it reading as rejection. Nobody discusses what happened; the sheet is about the two of them now.', '[{"id": "f0", "type": "textarea", "label": "Partner B: the feelings I have about what my partner went through"}, {"id": "f1", "type": "textarea", "label": "Partner B: where each one can go that is not my partner"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I can hear from my partner, and what I cannot right now"}, {"id": "f3", "type": "textarea", "label": "Partner B: the signal I will use when I need to step away for a while"}, {"id": "f4", "type": "textarea", "label": "Partner A: what I would like that signal to mean, and what it does not mean"}, {"id": "f5", "type": "textarea", "label": "Both: how we will check in on this in a month"}]'::jsonb, array['sexual abuse', 'couples', 'support', 'boundaries']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('skill-or-luck-attribution-check', 'Skill or Luck Attribution Check', 'cbt'::resource_kind, 'A sheet for reviewing a hard moment that passed and testing whether the client credits the skill they used or writes it off as luck.', 'Use it to build the belief that coping skills work by crediting them when they do.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients will use a skill, feel better, and then explain the relief by luck, timing or someone else showing up. That leaves the skill unlearned. After any moment that passed, walk through what they did, what changed and when, and have them write the explanation they reached for first. Then ask what evidence points to the skill itself. Rate how much credit they give the skill before and after. Be honest when time or luck did help; the aim is accurate credit, not cheerleading. Over a few weeks the sheet becomes a record of what has actually worked.', '[{"id": "f0", "type": "textarea", "label": "The hard moment that passed"}, {"id": "f1", "type": "textarea", "label": "The skill or skills I used, and when"}, {"id": "f2", "type": "textarea", "label": "What changed and roughly when"}, {"id": "f3", "type": "textarea", "label": "The explanation I reached for first"}, {"id": "f4", "type": "textarea", "label": "Evidence the skill itself made a difference"}, {"id": "f5", "type": "textarea", "label": "How much credit I gave the skill before this sheet, and how much now"}, {"id": "f6", "type": "textarea", "label": "What this tells me about using it next time"}]'::jsonb, array['coping skills', 'core CBT', 'automatic thoughts', 'self-talk']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('creative-hopelessness-coping-review', 'Creative Hopelessness Coping Review', 'act'::resource_kind, 'An ACT review of every strategy a client has used to get rid of a feeling, with what each cost and whether the feeling left.', 'Use it to open the question of whether the client''s coping is aimed at a fight that cannot be won.', array['Adults', 'Teens']::text[], '45 minutes', 'Run this before building a new skills menu, not after. List everything the client has tried to make the feeling go away, from distraction to planning to avoidance to substances, without judging any of it. For each, note what it cost and whether the feeling is gone for good. The point lands when the client sees the pattern themselves, so resist summarizing it for them. Stay with the discomfort of the list rather than rushing to willingness. Close by asking what they would be doing with the time and energy if the fight were not the job, and let that sit until next session.', '[{"id": "f0", "type": "textarea", "label": "Everything I have tried to make this feeling go away"}, {"id": "f1", "type": "textarea", "label": "What each one cost me in time, money, energy or relationships"}, {"id": "f2", "type": "textarea", "label": "Which ones made the feeling leave for good"}, {"id": "f3", "type": "textarea", "label": "What I notice looking at the whole list"}, {"id": "f4", "type": "textarea", "label": "What I would be doing with the energy if getting rid of the feeling were not the job"}, {"id": "f5", "type": "textarea", "label": "What I am willing to try differently"}]'::jsonb, array['coping skills', 'core ACT', 'willingness', 'acceptance']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('wise-mind-skill-pick-card', 'Wise Mind Skill Pick Card', 'dbt'::resource_kind, 'A DBT card for choosing a skill in a hard moment by hearing what emotion mind, reasonable mind and wise mind each pick.', 'Use it to stop a client reaching for the same skill every time regardless of the moment.', array['Adults', 'Teens']::text[], '20 minutes', 'The card has three columns and the client fills all three before acting. Emotion mind wants the fastest relief, reasonable mind wants the sensible option they will not do, and wise mind usually picks something in between. Practice with a recent moment so the client sees how different the three picks are. Clients who always use the same skill tend to be running on one mind only, which the card makes visible. Keep the skills on the card to ones they have already practiced; this is for choosing, not learning. Review which pick they followed and how it went.', '[{"id": "f0", "type": "textarea", "label": "The hard moment I am in or just had"}, {"id": "f1", "type": "textarea", "label": "What emotion mind wants to do right now"}, {"id": "f2", "type": "textarea", "label": "What reasonable mind says I should do"}, {"id": "f3", "type": "textarea", "label": "What wise mind picks, and how I know it is wise mind"}, {"id": "f4", "type": "textarea", "label": "The skill I actually used"}, {"id": "f5", "type": "textarea", "label": "How it went, and what I would pick next time"}]'::jsonb, array['coping skills', 'wise mind', 'core DBT', 'distress tolerance']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('both-tapped-out-coping-plan', 'Both Tapped Out Coping Plan', 'couples'::resource_kind, 'A plan for the evenings when both partners are depleted at once and neither can be the steady one.', 'Use it to keep a shared low point from turning into a fight over who gets to fall apart.', array['Couples']::text[], '30 minutes', 'Most couples have an unspoken rule that one of them holds it together, and the plan is for the nights when that rule fails. Each partner names what they need in the first twenty minutes, what they can offer when they have nothing left, and what they will not say. Agree on a phrase that means we are both done, a parallel reset (same room or separate, agreed in advance), and a time to reconnect. Watch for a partner who scores the night afterward or who always volunteers to be the steady one. Keep the plan short enough to remember when tired.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I can tell I am tapped out, and what I need in the first twenty minutes"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I can tell I am tapped out, and what I need in the first twenty minutes"}, {"id": "f2", "type": "textarea", "label": "Partner A: the small thing I can still offer when I have nothing left"}, {"id": "f3", "type": "textarea", "label": "Partner B: the small thing I can still offer when I have nothing left"}, {"id": "f4", "type": "textarea", "label": "The phrase that means we are both done tonight"}, {"id": "f5", "type": "textarea", "label": "What each of us does for the next hour, and whether we are in the same room"}, {"id": "f6", "type": "textarea", "label": "When and how we reconnect"}]'::jsonb, array['coping skills', 'couples', 'support', 'planning']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('coping-skills-hopscotch-course', 'Coping Skills Hopscotch Course', 'kids'::resource_kind, 'A chalk hopscotch course where every square holds a coping skill the child does before hopping on.', 'Use it to get skills into a child''s body through play.', array['Children']::text[], '30 minutes', 'The child draws the course with chalk outside or tape indoors and picks a skill for each square: a belly breath, a shoulder squeeze, naming a color, a silly face. The parent plays too, doing each skill the whole way and being bad at hopping on purpose so the child gets to coach. Keep the squares to skills the child already knows; the course is for rehearsal. Suggest the parent run it on a calm day so it is familiar before a hard one. If a child discloses harm during play, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "The skills I put in my squares"}, {"id": "f1", "type": "textarea", "label": "My favorite square and why"}, {"id": "f2", "type": "textarea", "label": "The square that is hardest to do"}, {"id": "f3", "type": "textarea", "label": "What my grown-up was like at hopscotch"}, {"id": "f4", "type": "textarea", "label": "When I could use one of my squares without the course"}, {"id": "f5", "type": "textarea", "label": "Who I would teach my course to"}]'::jsonb, array['coping skills', 'children', 'play', 'regulation']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('naming-the-fear-story-practice', 'Naming the Fear Story Practice', 'act'::resource_kind, 'An ACT defusion practice where the client gives their phobia''s story a title and greets it by name when it starts.', 'Use it to put a little distance between the client and the story their mind tells about the feared thing.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to write out the story their mind tells when the feared thing appears, start to finish, as if it were a short film. Then give it a title (Here comes the Dog Will Bite story) and practice saying the title out loud in a neutral voice. Rehearse in session with a photo or a mention, then on an easy step from their hierarchy. The story may stay exactly as loud; what changes is whether the client steps into it. Clients sometimes pick a mocking title and use it to argue with the fear, which is just a new fight. A plain title works better.', '[{"id": "f0", "type": "textarea", "label": "The story my mind tells when the feared thing shows up, start to finish"}, {"id": "f1", "type": "textarea", "label": "The title I am giving it"}, {"id": "f2", "type": "textarea", "label": "How I will greet it when it starts"}, {"id": "f3", "type": "textarea", "label": "What I noticed when I practiced the greeting in session"}, {"id": "f4", "type": "textarea", "label": "An easy step where I will try it this week"}, {"id": "f5", "type": "textarea", "label": "What the story did and what I did"}]'::jsonb, array['phobias', 'defusion', 'core ACT', 'exposure']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('self-soothe-after-an-approach-step-card', 'Self-Soothe After an Approach Step Card', 'dbt'::resource_kind, 'A DBT self-soothe card for the hour after an exposure step, so the client comes down without undoing the work.', 'Use it to plan aftercare that settles the body without turning into avoidance or reassurance.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients often undo a good step by rushing to a phone, a drink or someone to check they are okay. The card plans the hour afterward with the five senses before the step is taken, so settling does not become escape. Keep the soothing plain and short: a warm drink, a familiar song, a shower, a walk. Rule out anything that works as reassurance about the feared thing. Include a line for what they will tell themselves about the step, written in advance so it does not come from the fear. Review whether the aftercare helped them come back for the next step.', '[{"id": "f0", "type": "textarea", "label": "The step I am taking"}, {"id": "f1", "type": "textarea", "label": "Something for each sense that will settle me afterward"}, {"id": "f2", "type": "textarea", "label": "Things I will not do in the first hour because they would undo the step"}, {"id": "f3", "type": "textarea", "label": "What I will say to myself about the step, written now"}, {"id": "f4", "type": "textarea", "label": "Who I will tell, and what I want from them"}, {"id": "f5", "type": "textarea", "label": "How ready I felt for the next step"}]'::jsonb, array['phobias', 'self-soothing', 'core DBT', 'exposure']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('calm-modeling-plan-for-partners', 'Calm Modeling Plan for Partners', 'couples'::resource_kind, 'A plan where the partner without the fear demonstrates a calm approach while narrating it, and the fearful partner watches first.', 'Use it to add modeling to a couple''s exposure work before the fearful partner takes a step themselves.', array['Couples']::text[], '30 minutes', 'Watching someone handle the feared thing calmly, with a running commentary, is a step many clients can take before any direct contact. Partner B plans what they will do (open the window near the wasp, hold the needle kit, stand on the balcony) and the plain narration they will use: what they see, what their body is doing, that nothing is happening. No teasing, no surprises, no pulling the partner closer. Partner A sets the distance and the stop word and decides afterward whether they want a smaller version to try. Keep each demonstration under five minutes and repeat it rather than extend it.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the feared thing and the distance I can watch from"}, {"id": "f1", "type": "textarea", "label": "Partner A: my stop word and what I need my partner to do when I say it"}, {"id": "f2", "type": "textarea", "label": "Partner B: exactly what I will do, step by step"}, {"id": "f3", "type": "textarea", "label": "Partner B: the plain narration I will use while I do it"}, {"id": "f4", "type": "textarea", "label": "Partner B: what I will not do"}, {"id": "f5", "type": "textarea", "label": "Partner A: what I noticed watching, and whether I want a smaller version to try"}, {"id": "f6", "type": "textarea", "label": "Both: when we will repeat it"}]'::jsonb, array['phobias', 'couples', 'exposure', 'support']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('stuffed-stand-in-practice-play', 'Stuffed Stand-In Practice Play', 'kids'::resource_kind, 'A child practices approach steps on a toy or stuffed version of the feared thing before meeting the real one.', 'Use it to start graded steps with a stand-in a child can hold and boss around.', array['Children']::text[], 'Three sessions', 'Pick or make a stand-in: a plush dog, a plastic spider, a toy doctor kit for needles. The child decides where it sits in the room, then over several plays moves it closer, touches it, and finally takes charge of it, feeding the dog or giving the doll a shot. The parent follows the child''s pace, names feelings out loud and never springs the stand-in on them. Rate the fear with a finger count before and after each play. When the child can boss the stand-in around with ease, plan the first real-world step together. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "My stand-in and what I named it"}, {"id": "f1", "type": "textarea", "label": "Where it sits today"}, {"id": "f2", "type": "textarea", "label": "My fear fingers before and after I played with it"}, {"id": "f3", "type": "textarea", "label": "What I made my stand-in do"}, {"id": "f4", "type": "textarea", "label": "What my grown-up said while we played"}, {"id": "f5", "type": "textarea", "label": "What I want to try next time"}, {"id": "f6", "type": "textarea", "label": "The real thing I might meet when I am ready"}]'::jsonb, array['phobias', 'children', 'play', 'exposure']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('spot-the-safety-behavior-game', 'Spot the Safety Behavior Game', 'game'::resource_kind, 'A group game where one player acts out an approach to a feared thing with hidden safety behaviors and the others try to spot them.', 'Use it to teach a group to recognize the small habits that keep a fear going.', array['Groups', 'Teens', 'Adults']::text[], '40 minutes', 'Prepare cards naming a feared thing and two safety behaviors (gripping a phone, keeping the door in view, holding the breath, looking away, bringing a person). The actor draws a card and mimes a short approach while working the behaviors in. The rest watch and call them out; one point per correct spot, one to the actor for any behavior missed. Rotate so everyone acts once. Debrief with each player naming a safety behavior of their own and what dropping it might feel like. Keep the mimes light; nobody is asked to do real exposure in the game.', '[{"id": "f0", "type": "textarea", "label": "The card I acted and the behaviors I hid"}, {"id": "f1", "type": "textarea", "label": "The behaviors I spotted in other players"}, {"id": "f2", "type": "textarea", "label": "Which ones were hardest to see, and why"}, {"id": "f3", "type": "textarea", "label": "A safety behavior I use with my own fear"}, {"id": "f4", "type": "textarea", "label": "What dropping it might feel like"}, {"id": "f5", "type": "textarea", "label": "One I am willing to leave out on my next step"}]'::jsonb, array['phobias', 'safety behaviors', 'group', 'play']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('dear-man-for-unwanted-appearance-comments', 'DEAR MAN for Unwanted Appearance Comments', 'dbt'::resource_kind, 'A DEAR MAN script for asking a family member or friend to stop commenting on the client''s appearance.', 'Use it to script the ask that most clients have been rehearsing silently for years.', array['Adults', 'Teens']::text[], '30 minutes', 'Pick one person and one recurring comment, not the whole family. Build the script in order: describe the comment plainly, express how it lands, assert the specific ask, reinforce what it would do for the relationship. Then plan staying mindful if the person argues, appearing confident, and what the client is willing to negotiate (a gentler reminder, a code word at the table). The usual trip is a describe step that includes a judgment; keep it to the words the person says. Rehearse with you playing the relative at their worst, and agree how the client will handle it if the comments continue.', '[{"id": "f0", "type": "textarea", "label": "The person and the comment they keep making"}, {"id": "f1", "type": "textarea", "label": "Describe: the comment, in their words, without my opinion of it"}, {"id": "f2", "type": "textarea", "label": "Express: how it lands for me"}, {"id": "f3", "type": "textarea", "label": "Assert: exactly what I am asking them to do instead"}, {"id": "f4", "type": "textarea", "label": "Reinforce: what it would do for us"}, {"id": "f5", "type": "textarea", "label": "What I will say if they argue or make it about them"}, {"id": "f6", "type": "textarea", "label": "What I am willing to negotiate, and what I am not"}]'::jsonb, array['body image', 'DEAR MAN', 'interpersonal effectiveness', 'boundaries']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('avoided-activities-reclaim-plan-for-two', 'Avoided Activities Reclaim Plan for Two', 'couples'::resource_kind, 'A plan for the things a couple has quietly stopped doing because one partner feels exposed, such as swimming, dancing or being in photos.', 'Use it to bring back shared activities one small, agreed step at a time.', array['Couples']::text[], '40 minutes', 'Couples rarely name the activities they have dropped; they just stop suggesting them. Each partner lists what they miss doing together, and Partner A says which ones feel exposing. Choose one and plan the smallest version: a quiet pool at an off hour, dancing in the kitchen, one photo that stays on a phone. Partner B''s job is to go along without commenting on how Partner A looks, before, during or after. Agree on the words that help and a signal for leaving early without a post-mortem. Keep every conversation on what they did together, never on the body.', '[{"id": "f0", "type": "textarea", "label": "Partner A: things we used to do together that I now avoid"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I miss doing with my partner"}, {"id": "f2", "type": "textarea", "label": "Both: the one activity we will bring back first, in its smallest version"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I will say and what I will not say about appearance before, during and after"}, {"id": "f4", "type": "textarea", "label": "Partner A: the signal I will use if I need to leave early"}, {"id": "f5", "type": "textarea", "label": "Both: what we will do right after, with no debrief about looks"}, {"id": "f6", "type": "textarea", "label": "Both: how it went, and the next version"}]'::jsonb, array['body image', 'couples', 'avoidance', 'connection']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('who-i-am-trading-card-craft', 'Who I Am Trading Card Craft', 'kids'::resource_kind, 'A child designs a trading card of themselves with stats for kindness, courage and skills and no line for looks.', 'Use it to give a child a picture of themselves that is about what they do and who they are.', array['Children']::text[], '30 minutes', 'Give the child a blank card template with a space for a drawing and five stat lines they choose: fast runner, good at jokes, brave with spiders, kind to the cat. Explain the one rule: nothing about how anyone looks. The parent makes their own card beside the child, following the same rule, and the two trade and read each other''s stats aloud. Watch for a parent who sneaks in a looks comment as praise; redirect gently to a doing stat. The cards go on the fridge. If a child discloses harm during the craft, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "My card name and the picture I drew"}, {"id": "f1", "type": "textarea", "label": "My five stats"}, {"id": "f2", "type": "textarea", "label": "The stat I am proudest of"}, {"id": "f3", "type": "textarea", "label": "A stat my grown-up gave me that surprised me"}, {"id": "f4", "type": "textarea", "label": "The stats on my grown-up''s card"}, {"id": "f5", "type": "textarea", "label": "A stat I want to grow next"}]'::jsonb, array['body image', 'children', 'strengths', 'art']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('appearance-talk-buzzer-game', 'Appearance Talk Buzzer Game', 'game'::resource_kind, 'A group game where players improvise an everyday conversation and anyone can buzz an appearance comment and redo the line.', 'Use it to help a group hear how much everyday talk is about looks and practice saying something else.', array['Groups', 'Teens', 'Adults']::text[], '40 minutes', 'Give two players a scene (meeting at a party, a family dinner, a reunion) and let them improvise for two minutes. Anyone watching can buzz when a line is about someone''s appearance, including compliments. The speaker then redoes the line about something else: what the person did, said or is like. One point per fair buzz, one to the speaker for a good redo. Rotate until everyone has played a scene. Debrief on which comments were hardest to replace, which felt like a loss, and what a conversation sounds like when looks are off the table. Keep buzzing playful.', '[{"id": "f0", "type": "textarea", "label": "The scene I played"}, {"id": "f1", "type": "textarea", "label": "The lines I got buzzed on"}, {"id": "f2", "type": "textarea", "label": "How I redid them"}, {"id": "f3", "type": "textarea", "label": "The appearance comment that was hardest to replace"}, {"id": "f4", "type": "textarea", "label": "What I noticed about conversations with looks off the table"}, {"id": "f5", "type": "textarea", "label": "One thing I will say instead this week"}]'::jsonb, array['body image', 'group', 'play', 'communication']::text[], '2026-10-07T15:00:00+00:00'::timestamptz),
  ('closet-comfort-inventory', 'Closet Comfort Inventory', 'worksheet'::resource_kind, 'An inventory of a client''s clothes sorted by how they feel to wear and move in rather than how they look.', 'Use it to move getting dressed from a daily judgment to a question of comfort and use.', array['Adults', 'Teens']::text[], 'One week', 'Over a week the client notes what they wore and rates only comfort, ease of movement and whether the day''s plans were possible in it. No rating for how it looked. Many clients discover a handful of items they wear because they feel right and a larger set kept for a day they expect to look different. The second set is the conversation: what it costs to keep it in view, and whether storing it elsewhere is a kindness. Keep the sheet away from any talk of the body itself; the subject is the clothes. Review which items make a hard morning easier.', '[{"id": "f0", "type": "textarea", "label": "What I wore each day this week"}, {"id": "f1", "type": "textarea", "label": "How each felt to wear and move in"}, {"id": "f2", "type": "textarea", "label": "Whether I could do what the day needed in it"}, {"id": "f3", "type": "textarea", "label": "Clothes I keep for a day I expect to be different"}, {"id": "f4", "type": "textarea", "label": "What keeping those in view costs me each morning"}, {"id": "f5", "type": "textarea", "label": "Items that make a hard morning easier"}, {"id": "f6", "type": "textarea", "label": "What I will do with the rest"}]'::jsonb, array['body image', 'self-monitoring', 'self-compassion', 'habits']::text[], '2026-10-07T15:00:00+00:00'::timestamptz)
